/** static bool8 AccuracyCalcHelper(u16 move) */
export function AccuracyCalcHelper(move: any): any {
  if (gStatuses3[gBattlerTarget] & STATUS3_ALWAYS_HITS && gDisableStructs[gBattlerTarget].battlerWithSureHit == gBattlerAttacker)
      {
          JumpIfMoveFailed(7, move);
          return TRUE;
      }

      if (!(gHitMarker & HITMARKER_IGNORE_ON_AIR) && gStatuses3[gBattlerTarget] & STATUS3_ON_AIR)
      {
          gMoveResultFlags |= MOVE_RESULT_MISSED;
          JumpIfMoveFailed(7, move);
          return TRUE;
      }

      gHitMarker &= ~HITMARKER_IGNORE_ON_AIR;

      if (!(gHitMarker & HITMARKER_IGNORE_UNDERGROUND) && gStatuses3[gBattlerTarget] & STATUS3_UNDERGROUND)
      {
          gMoveResultFlags |= MOVE_RESULT_MISSED;
          JumpIfMoveFailed(7, move);
          return TRUE;
      }

      gHitMarker &= ~HITMARKER_IGNORE_UNDERGROUND;

      if (!(gHitMarker & HITMARKER_IGNORE_UNDERWATER) && gStatuses3[gBattlerTarget] & STATUS3_UNDERWATER)
      {
          gMoveResultFlags |= MOVE_RESULT_MISSED;
          JumpIfMoveFailed(7, move);
          return TRUE;
      }

      gHitMarker &= ~HITMARKER_IGNORE_UNDERWATER;

      if ((WEATHER_HAS_EFFECT && (gBattleWeather & B_WEATHER_RAIN) && gBattleMoves[move].effect == EFFECT_THUNDER)
       || (gBattleMoves[move].effect == EFFECT_ALWAYS_HIT || gBattleMoves[move].effect == EFFECT_VITAL_THROW))
      {
          JumpIfMoveFailed(7, move);
          return TRUE;
      }

      return FALSE;
}

/** static void Cmd_accuracycheck(void) */
export function Cmd_accuracycheck(): any {
  let move: any = T2_READ_16(gBattlescriptCurrInstr + 5);

      if (move == NO_ACC_CALC || move == NO_ACC_CALC_CHECK_LOCK_ON)
      {
          if (gStatuses3[gBattlerTarget] & STATUS3_ALWAYS_HITS && move == NO_ACC_CALC_CHECK_LOCK_ON && gDisableStructs[gBattlerTarget].battlerWithSureHit == gBattlerAttacker)
              gBattlescriptCurrInstr += 7;
          else if (gStatuses3[gBattlerTarget] & (STATUS3_ON_AIR | STATUS3_UNDERGROUND | STATUS3_UNDERWATER))
              gBattlescriptCurrInstr = T1_READ_PTR(gBattlescriptCurrInstr + 1);
          else if (!JumpIfMoveAffectedByProtect(0))
              gBattlescriptCurrInstr += 7;
      }
      else
      {
          let type, moveAcc, holdEffect, param;
          let buff: any = null;
          let calc: any = null;

          if (move == ACC_CURR_MOVE)
              move = gCurrentMove;

          GET_MOVE_TYPE(move, type);

          if (JumpIfMoveAffectedByProtect(move))
              return;
          if (AccuracyCalcHelper(move))
              return;

          if (gBattleMons[gBattlerTarget].status2 & STATUS2_FORESIGHT)
          {
              let acc: any = gBattleMons[gBattlerAttacker].statStages[STAT_ACC];
              buff = acc;
          }
          else
          {
              let acc: any = gBattleMons[gBattlerAttacker].statStages[STAT_ACC];
              buff = acc + DEFAULT_STAT_STAGE - gBattleMons[gBattlerTarget].statStages[STAT_EVASION];
          }

          if (buff < MIN_STAT_STAGE)
              buff = MIN_STAT_STAGE;
          if (buff > MAX_STAT_STAGE)
              buff = MAX_STAT_STAGE;

          moveAcc = gBattleMoves[move].accuracy;
           
          if (WEATHER_HAS_EFFECT && gBattleWeather & B_WEATHER_SUN && gBattleMoves[move].effect == EFFECT_THUNDER)
              moveAcc = 50;

          calc = sAccuracyStageRatios[buff].dividend * moveAcc;
          calc /= sAccuracyStageRatios[buff].divisor;

          if (gBattleMons[gBattlerAttacker].ability == ABILITY_COMPOUND_EYES)
              calc = (calc * 130) / 100;  
          if (WEATHER_HAS_EFFECT && gBattleMons[gBattlerTarget].ability == ABILITY_SAND_VEIL && gBattleWeather & B_WEATHER_SANDSTORM)
              calc = (calc * 80) / 100;  
          if (gBattleMons[gBattlerAttacker].ability == ABILITY_HUSTLE && IS_TYPE_PHYSICAL(type))
              calc = (calc * 80) / 100;  

          if (gBattleMons[gBattlerTarget].item == ITEM_ENIGMA_BERRY)
          {
              holdEffect = gEnigmaBerries[gBattlerTarget].holdEffect;
              param = gEnigmaBerries[gBattlerTarget].holdEffectParam;
          }
          else
          {
              holdEffect = GetItemHoldEffect(gBattleMons[gBattlerTarget].item);
              param = GetItemHoldEffectParam(gBattleMons[gBattlerTarget].item);
          }

          gPotentialItemEffectBattler = gBattlerTarget;

          if (holdEffect == HOLD_EFFECT_EVASION_UP)
              calc = (calc * (100 - param)) / 100;

           
          if ((Random() % 100 + 1) > calc)
          {
              gMoveResultFlags |= MOVE_RESULT_MISSED;
              if (gBattleTypeFlags & BATTLE_TYPE_DOUBLE
               && (gBattleMoves[move].target == MOVE_TARGET_BOTH || gBattleMoves[move].target == MOVE_TARGET_FOES_AND_ALLY))
                  gBattleCommunication[MISS_TYPE] = B_MSG_AVOIDED_ATK;
              else
                  gBattleCommunication[MISS_TYPE] = B_MSG_MISSED;

              CheckWonderGuardAndLevitate();
          }
          JumpIfMoveFailed(7, move);
      }
}

