/** static void Cmd_ppreduce(void) */
export function Cmd_ppreduce(): any {
  let ppToDeduct: any = 1;

      if (gBattleControllerExecFlags)
          return;

      if (!gSpecialStatuses[gBattlerAttacker].ppNotAffectedByPressure)
      {
          switch (gBattleMoves[gCurrentMove].target)
          {
          case MOVE_TARGET_FOES_AND_ALLY:
              ppToDeduct += AbilityBattleEffects(ABILITYEFFECT_COUNT_ON_FIELD, gBattlerAttacker, ABILITY_PRESSURE, 0, 0);
              break;
          case MOVE_TARGET_BOTH:
          case MOVE_TARGET_OPPONENTS_FIELD:
              ppToDeduct += AbilityBattleEffects(ABILITYEFFECT_COUNT_OTHER_SIDE, gBattlerAttacker, ABILITY_PRESSURE, 0, 0);
              break;
          default:
              if (gBattlerAttacker != gBattlerTarget && gBattleMons[gBattlerTarget].ability == ABILITY_PRESSURE)
                  ppToDeduct++;
              break;
          }
      }

      if (!(gHitMarker & (HITMARKER_NO_PPDEDUCT | HITMARKER_NO_ATTACKSTRING)) && gBattleMons[gBattlerAttacker].pp[gCurrMovePos])
      {
          gProtectStructs[gBattlerAttacker].notFirstStrike = 1;

          if (gBattleMons[gBattlerAttacker].pp[gCurrMovePos] > ppToDeduct)
              gBattleMons[gBattlerAttacker].pp[gCurrMovePos] -= ppToDeduct;
          else
              gBattleMons[gBattlerAttacker].pp[gCurrMovePos] = 0;

          if (MOVE_IS_PERMANENT(gBattlerAttacker, gCurrMovePos))
          {
              gActiveBattler = gBattlerAttacker;
              BtlController_EmitSetMonData(B_COMM_TO_CONTROLLER, REQUEST_PPMOVE1_BATTLE + gCurrMovePos, 0,
                                           sizeof(gBattleMons[gBattlerAttacker].pp[gCurrMovePos]),gBattleMons[gBattlerAttacker].pp[gCurrMovePos]);
              MarkBattlerForControllerExec(gBattlerAttacker);
          }
      }

      gHitMarker &= ~HITMARKER_NO_PPDEDUCT;
      gBattlescriptCurrInstr++;
}

/** static void Cmd_critcalc(void) */
export function Cmd_critcalc(): any {
  let holdEffect: any = null;
      let item, critChance;

      item = gBattleMons[gBattlerAttacker].item;

      if (item == ITEM_ENIGMA_BERRY)
          holdEffect = gEnigmaBerries[gBattlerAttacker].holdEffect;
      else
          holdEffect = GetItemHoldEffect(item);

      gPotentialItemEffectBattler = gBattlerAttacker;

      critChance  = 2 * ((gBattleMons[gBattlerAttacker].status2 & STATUS2_FOCUS_ENERGY) != 0)
                  + (gBattleMoves[gCurrentMove].effect == EFFECT_HIGH_CRITICAL)
                  + (gBattleMoves[gCurrentMove].effect == EFFECT_SKY_ATTACK)
                  + (gBattleMoves[gCurrentMove].effect == EFFECT_BLAZE_KICK)
                  + (gBattleMoves[gCurrentMove].effect == EFFECT_POISON_TAIL)
                  + (holdEffect == HOLD_EFFECT_SCOPE_LENS)
                  + 2 * (holdEffect == HOLD_EFFECT_LUCKY_PUNCH && gBattleMons[gBattlerAttacker].species == SPECIES_CHANSEY)
                  + 2 * (holdEffect == HOLD_EFFECT_STICK && gBattleMons[gBattlerAttacker].species == SPECIES_FARFETCHD);

      if (critChance >= ARRAY_COUNT(sCriticalHitChance))
          critChance = ARRAY_COUNT(sCriticalHitChance) - 1;

      if ((gBattleMons[gBattlerTarget].ability != ABILITY_BATTLE_ARMOR && gBattleMons[gBattlerTarget].ability != ABILITY_SHELL_ARMOR)
       && !(gStatuses3[gBattlerAttacker] & STATUS3_CANT_SCORE_A_CRIT)
       && !(gBattleTypeFlags & (BATTLE_TYPE_WALLY_TUTORIAL | BATTLE_TYPE_FIRST_BATTLE))
       && !(Random() % sCriticalHitChance[critChance]))
          gCritMultiplier = 2;
      else
          gCritMultiplier = 1;

      gBattlescriptCurrInstr++;
}

/** static void Cmd_damagecalc(void) */
export function Cmd_damagecalc(): any {
  let sideStatus: any = gSideStatuses[GET_BATTLER_SIDE(gBattlerTarget)];
      gBattleMoveDamage = CalculateBaseDamage(gBattleMons[gBattlerAttacker],gBattleMons[gBattlerTarget], gCurrentMove,
                                              sideStatus, gDynamicBasePower,
                                              gBattleStruct.dynamicMoveType, gBattlerAttacker, gBattlerTarget);
      gBattleMoveDamage = gBattleMoveDamage * gCritMultiplier * gBattleScripting.dmgMultiplier;

      if (gStatuses3[gBattlerAttacker] & STATUS3_CHARGED_UP && gBattleMoves[gCurrentMove].type == TYPE_ELECTRIC)
          gBattleMoveDamage *= 2;
      if (gProtectStructs[gBattlerAttacker].helpingHand)
          gBattleMoveDamage = gBattleMoveDamage * 15 / 10;

      gBattlescriptCurrInstr++;
}

/** void AI_CalcDmg(u8 attacker, u8 defender) */
export function AI_CalcDmg(attacker: any, defender: any): any {
  let sideStatus: any = gSideStatuses[GET_BATTLER_SIDE(defender)];
      gBattleMoveDamage = CalculateBaseDamage(gBattleMons[attacker],gBattleMons[defender], gCurrentMove,
                                              sideStatus, gDynamicBasePower,
                                              gBattleStruct.dynamicMoveType, attacker, defender);
      gDynamicBasePower = 0;
      gBattleMoveDamage = gBattleMoveDamage * gCritMultiplier * gBattleScripting.dmgMultiplier;

      if (gStatuses3[attacker] & STATUS3_CHARGED_UP && gBattleMoves[gCurrentMove].type == TYPE_ELECTRIC)
          gBattleMoveDamage *= 2;
      if (gProtectStructs[attacker].helpingHand)
          gBattleMoveDamage = gBattleMoveDamage * 15 / 10;
}

/** static void ModulateDmgByType(u8 multiplier) */
export function ModulateDmgByType(multiplier: any): any {
  gBattleMoveDamage = gBattleMoveDamage * multiplier / 10;
      if (gBattleMoveDamage == 0 && multiplier != 0)
          gBattleMoveDamage = 1;

      switch (multiplier)
      {
      case TYPE_MUL_NO_EFFECT:
          gMoveResultFlags |= MOVE_RESULT_DOESNT_AFFECT_FOE;
          gMoveResultFlags &= ~MOVE_RESULT_NOT_VERY_EFFECTIVE;
          gMoveResultFlags &= ~MOVE_RESULT_SUPER_EFFECTIVE;
          break;
      case TYPE_MUL_NOT_EFFECTIVE:
          if (gBattleMoves[gCurrentMove].power && !(gMoveResultFlags & MOVE_RESULT_NO_EFFECT))
          {
              if (gMoveResultFlags & MOVE_RESULT_SUPER_EFFECTIVE)
                  gMoveResultFlags &= ~MOVE_RESULT_SUPER_EFFECTIVE;
              else
                  gMoveResultFlags |= MOVE_RESULT_NOT_VERY_EFFECTIVE;
          }
          break;
      case TYPE_MUL_SUPER_EFFECTIVE:
          if (gBattleMoves[gCurrentMove].power && !(gMoveResultFlags & MOVE_RESULT_NO_EFFECT))
          {
              if (gMoveResultFlags & MOVE_RESULT_NOT_VERY_EFFECTIVE)
                  gMoveResultFlags &= ~MOVE_RESULT_NOT_VERY_EFFECTIVE;
              else
                  gMoveResultFlags |= MOVE_RESULT_SUPER_EFFECTIVE;
          }
          break;
      }
}

/** static void Cmd_typecalc(void) */
export function Cmd_typecalc(): any {
  let i: any = 0;
      let moveType: any = null;

      if (gCurrentMove == MOVE_STRUGGLE)
      {
          gBattlescriptCurrInstr++;
          return;
      }

      GET_MOVE_TYPE(gCurrentMove, moveType);

       
      if (IS_BATTLER_OF_TYPE(gBattlerAttacker, moveType))
      {
          gBattleMoveDamage = gBattleMoveDamage * 15;
          gBattleMoveDamage = gBattleMoveDamage / 10;
      }

      if (gBattleMons[gBattlerTarget].ability == ABILITY_LEVITATE && moveType == TYPE_GROUND)
      {
          gLastUsedAbility = gBattleMons[gBattlerTarget].ability;
          gMoveResultFlags |= (MOVE_RESULT_MISSED | MOVE_RESULT_DOESNT_AFFECT_FOE);
          gLastLandedMoves[gBattlerTarget] = 0;
          gLastHitByType[gBattlerTarget] = 0;
          gBattleCommunication[MISS_TYPE] = B_MSG_GROUND_MISS;
          RecordAbilityBattle(gBattlerTarget, gLastUsedAbility);
      }
      else
      {
          while (TYPE_EFFECT_ATK_TYPE(i) != TYPE_ENDTABLE)
          {
              if (TYPE_EFFECT_ATK_TYPE(i) == TYPE_FORESIGHT)
              {
                  if (gBattleMons[gBattlerTarget].status2 & STATUS2_FORESIGHT)
                      break;
                  i += 3;
                  continue;
              }
              else if (TYPE_EFFECT_ATK_TYPE(i) == moveType)
              {
                   
                  if (TYPE_EFFECT_DEF_TYPE(i) == gBattleMons[gBattlerTarget].types[0])
                      ModulateDmgByType(TYPE_EFFECT_MULTIPLIER(i));
                   
                  if (TYPE_EFFECT_DEF_TYPE(i) == gBattleMons[gBattlerTarget].types[1] &&
                      gBattleMons[gBattlerTarget].types[0] != gBattleMons[gBattlerTarget].types[1])
                      ModulateDmgByType(TYPE_EFFECT_MULTIPLIER(i));
              }
              i += 3;
          }
      }

      if (gBattleMons[gBattlerTarget].ability == ABILITY_WONDER_GUARD && AttacksThisTurn(gBattlerAttacker, gCurrentMove) == 2
       && (!(gMoveResultFlags & MOVE_RESULT_SUPER_EFFECTIVE) || ((gMoveResultFlags & (MOVE_RESULT_SUPER_EFFECTIVE | MOVE_RESULT_NOT_VERY_EFFECTIVE)) == (MOVE_RESULT_SUPER_EFFECTIVE | MOVE_RESULT_NOT_VERY_EFFECTIVE)))
       && gBattleMoves[gCurrentMove].power)
      {
          gLastUsedAbility = ABILITY_WONDER_GUARD;
          gMoveResultFlags |= MOVE_RESULT_MISSED;
          gLastLandedMoves[gBattlerTarget] = 0;
          gLastHitByType[gBattlerTarget] = 0;
          gBattleCommunication[MISS_TYPE] = B_MSG_AVOIDED_DMG;
          RecordAbilityBattle(gBattlerTarget, gLastUsedAbility);
      }
      if (gMoveResultFlags & MOVE_RESULT_DOESNT_AFFECT_FOE)
          gProtectStructs[gBattlerAttacker].targetNotAffected = 1;

      gBattlescriptCurrInstr++;
}

/** static void CheckWonderGuardAndLevitate(void) */
export function CheckWonderGuardAndLevitate(): any {
  let flags: any = 0;
      let i: any = 0;
      let moveType: any = null;

      if (gCurrentMove == MOVE_STRUGGLE || !gBattleMoves[gCurrentMove].power)
          return;

      GET_MOVE_TYPE(gCurrentMove, moveType);

      if (gBattleMons[gBattlerTarget].ability == ABILITY_LEVITATE && moveType == TYPE_GROUND)
      {
          gLastUsedAbility = ABILITY_LEVITATE;
          gBattleCommunication[MISS_TYPE] = B_MSG_GROUND_MISS;
          RecordAbilityBattle(gBattlerTarget, ABILITY_LEVITATE);
          return;
      }

      while (TYPE_EFFECT_ATK_TYPE(i) != TYPE_ENDTABLE)
      {
          if (TYPE_EFFECT_ATK_TYPE(i) == TYPE_FORESIGHT)
          {
              if (gBattleMons[gBattlerTarget].status2 & STATUS2_FORESIGHT)
                  break;
              i += 3;
              continue;
          }
          if (TYPE_EFFECT_ATK_TYPE(i) == moveType)
          {
               
              if (TYPE_EFFECT_DEF_TYPE(i) == gBattleMons[gBattlerTarget].types[0]
                  && TYPE_EFFECT_MULTIPLIER(i) == TYPE_MUL_NO_EFFECT)
              {
                  gMoveResultFlags |= MOVE_RESULT_DOESNT_AFFECT_FOE;
                  gProtectStructs[gBattlerAttacker].targetNotAffected = 1;
              }
              if (TYPE_EFFECT_DEF_TYPE(i) == gBattleMons[gBattlerTarget].types[1] &&
                  gBattleMons[gBattlerTarget].types[0] != gBattleMons[gBattlerTarget].types[1] &&
                  TYPE_EFFECT_MULTIPLIER(i) == TYPE_MUL_NO_EFFECT)
              {
                  gMoveResultFlags |= MOVE_RESULT_DOESNT_AFFECT_FOE;
                  gProtectStructs[gBattlerAttacker].targetNotAffected = 1;
              }

               
              if (TYPE_EFFECT_DEF_TYPE(i) == gBattleMons[gBattlerTarget].types[0] && TYPE_EFFECT_MULTIPLIER(i) == 20)
                  flags |= 1;
              if (TYPE_EFFECT_DEF_TYPE(i) == gBattleMons[gBattlerTarget].types[1]
               && gBattleMons[gBattlerTarget].types[0] != gBattleMons[gBattlerTarget].types[1]
               && TYPE_EFFECT_MULTIPLIER(i) == TYPE_MUL_SUPER_EFFECTIVE)
                  flags |= 1;

               
              if (TYPE_EFFECT_DEF_TYPE(i) == gBattleMons[gBattlerTarget].types[0] && TYPE_EFFECT_MULTIPLIER(i) == 5)
                  flags |= 2;
              if (TYPE_EFFECT_DEF_TYPE(i) == gBattleMons[gBattlerTarget].types[1]
               && gBattleMons[gBattlerTarget].types[0] != gBattleMons[gBattlerTarget].types[1]
               && TYPE_EFFECT_MULTIPLIER(i) == TYPE_MUL_NOT_EFFECTIVE)
                  flags |= 2;
          }
          i += 3;
      }

      if (gBattleMons[gBattlerTarget].ability == ABILITY_WONDER_GUARD && AttacksThisTurn(gBattlerAttacker, gCurrentMove) == 2)
      {
          if (((flags & 2) || !(flags & 1)) && gBattleMoves[gCurrentMove].power)
          {
              gLastUsedAbility = ABILITY_WONDER_GUARD;
              gBattleCommunication[MISS_TYPE] = B_MSG_AVOIDED_DMG;
              RecordAbilityBattle(gBattlerTarget, ABILITY_WONDER_GUARD);
          }
      }
}

/** static void ModulateDmgByType2(u8 multiplier, u16 move, u8 *flags) */
export function ModulateDmgByType2(multiplier: any, move: any, flags: any): any {
  gBattleMoveDamage = gBattleMoveDamage * multiplier / 10;
      if (gBattleMoveDamage == 0 && multiplier != 0)
          gBattleMoveDamage = 1;

      switch (multiplier)
      {
      case TYPE_MUL_NO_EFFECT:
          flags |= MOVE_RESULT_DOESNT_AFFECT_FOE;
          flags &= ~MOVE_RESULT_NOT_VERY_EFFECTIVE;
          flags &= ~MOVE_RESULT_SUPER_EFFECTIVE;
          break;
      case TYPE_MUL_NOT_EFFECTIVE:
          if (gBattleMoves[move].power && !(flags & MOVE_RESULT_NO_EFFECT))
          {
              if (flags & MOVE_RESULT_SUPER_EFFECTIVE)
                  flags &= ~MOVE_RESULT_SUPER_EFFECTIVE;
              else
                  flags |= MOVE_RESULT_NOT_VERY_EFFECTIVE;
          }
          break;
      case TYPE_MUL_SUPER_EFFECTIVE:
          if (gBattleMoves[move].power && !(flags & MOVE_RESULT_NO_EFFECT))
          {
              if (flags & MOVE_RESULT_NOT_VERY_EFFECTIVE)
                  flags &= ~MOVE_RESULT_NOT_VERY_EFFECTIVE;
              else
                  flags |= MOVE_RESULT_SUPER_EFFECTIVE;
          }
          break;
      }
}

/** u8 TypeCalc(u16 move, u8 attacker, u8 defender) */
export function TypeCalc(move: any, attacker: any, defender: any): any {
  let i: any = 0;
      let flags: any = 0;
      let moveType: any = null;

      if (move == MOVE_STRUGGLE)
          return 0;

      moveType = gBattleMoves[move].type;

       
      if (IS_BATTLER_OF_TYPE(attacker, moveType))
      {
          gBattleMoveDamage = gBattleMoveDamage * 15;
          gBattleMoveDamage = gBattleMoveDamage / 10;
      }

      if (gBattleMons[defender].ability == ABILITY_LEVITATE && moveType == TYPE_GROUND)
      {
          flags |= (MOVE_RESULT_MISSED | MOVE_RESULT_DOESNT_AFFECT_FOE);
      }
      else
      {
          while (TYPE_EFFECT_ATK_TYPE(i) != TYPE_ENDTABLE)
          {
              if (TYPE_EFFECT_ATK_TYPE(i) == TYPE_FORESIGHT)
              {
                  if (gBattleMons[defender].status2 & STATUS2_FORESIGHT)
                      break;
                  i += 3;
                  continue;
              }

              else if (TYPE_EFFECT_ATK_TYPE(i) == moveType)
              {
                   
                  if (TYPE_EFFECT_DEF_TYPE(i) == gBattleMons[defender].types[0])
                      ModulateDmgByType2(TYPE_EFFECT_MULTIPLIER(i), move,flags);
                   
                  if (TYPE_EFFECT_DEF_TYPE(i) == gBattleMons[defender].types[1] &&
                      gBattleMons[defender].types[0] != gBattleMons[defender].types[1])
                      ModulateDmgByType2(TYPE_EFFECT_MULTIPLIER(i), move,flags);
              }
              i += 3;
          }
      }

      if (gBattleMons[defender].ability == ABILITY_WONDER_GUARD && !(flags & MOVE_RESULT_MISSED)
          && AttacksThisTurn(attacker, move) == 2
          && (!(flags & MOVE_RESULT_SUPER_EFFECTIVE) || ((flags & (MOVE_RESULT_SUPER_EFFECTIVE | MOVE_RESULT_NOT_VERY_EFFECTIVE)) == (MOVE_RESULT_SUPER_EFFECTIVE | MOVE_RESULT_NOT_VERY_EFFECTIVE)))
          && gBattleMoves[move].power)
      {
          flags |= MOVE_RESULT_MISSED;
      }
      return flags;
}

/** u8 AI_TypeCalc(u16 move, u16 targetSpecies, u8 targetAbility) */
export function AI_TypeCalc(move: any, targetSpecies: any, targetAbility: any): any {
  let i: any = 0;
      let flags: any = 0;
      let type1: any = gSpeciesInfo[targetSpecies].types[0], type2 = gSpeciesInfo[targetSpecies].types[1];
      let moveType: any = null;

      if (move == MOVE_STRUGGLE)
          return 0;

      moveType = gBattleMoves[move].type;

      if (targetAbility == ABILITY_LEVITATE && moveType == TYPE_GROUND)
      {
          flags = MOVE_RESULT_MISSED | MOVE_RESULT_DOESNT_AFFECT_FOE;
      }
      else
      {
          while (TYPE_EFFECT_ATK_TYPE(i) != TYPE_ENDTABLE)
          {
              if (TYPE_EFFECT_ATK_TYPE(i) == TYPE_FORESIGHT)
              {
                  i += 3;
                  continue;
              }
              if (TYPE_EFFECT_ATK_TYPE(i) == moveType)
              {
                   
                  if (TYPE_EFFECT_DEF_TYPE(i) == type1)
                      ModulateDmgByType2(TYPE_EFFECT_MULTIPLIER(i), move,flags);
                   
                  if (TYPE_EFFECT_DEF_TYPE(i) == type2 && type1 != type2)
                      ModulateDmgByType2(TYPE_EFFECT_MULTIPLIER(i), move,flags);
              }
              i += 3;
          }
      }
      if (targetAbility == ABILITY_WONDER_GUARD
       && (!(flags & MOVE_RESULT_SUPER_EFFECTIVE) || ((flags & (MOVE_RESULT_SUPER_EFFECTIVE | MOVE_RESULT_NOT_VERY_EFFECTIVE)) == (MOVE_RESULT_SUPER_EFFECTIVE | MOVE_RESULT_NOT_VERY_EFFECTIVE)))
       && gBattleMoves[move].power)
          flags |= MOVE_RESULT_DOESNT_AFFECT_FOE;
      return flags;
}

/** static inline void ApplyRandomDmgMultiplier(void) */
export function ApplyRandomDmgMultiplier(): any {
  let rand: any = Random();
      let randPercent: any = 100 - (rand % 16);

      if (gBattleMoveDamage != 0)
      {
          gBattleMoveDamage *= randPercent;
          gBattleMoveDamage /= 100;
          if (gBattleMoveDamage == 0)
              gBattleMoveDamage = 1;
      }
}

/** static void Cmd_adjustnormaldamage(void) */
export function Cmd_adjustnormaldamage(): any {
  let holdEffect, param;

      ApplyRandomDmgMultiplier();

      if (gBattleMons[gBattlerTarget].item == ITEM_ENIGMA_BERRY)
      {
          holdEffect = gEnigmaBerries[gBattlerTarget].holdEffect;
          param = gEnigmaBerries[gBattlerTarget].holdEffectParam;
      }
      else
      {
          holdEffect = GetItemHoldEffect(gBattleMons[gBattlerTarget].item);
          param = GetItemHoldEffectParam(gBattleMons[gBattlerTarget].item);
      }

      gPotentialItemEffectBattler = gBattlerTarget;

      if (holdEffect == HOLD_EFFECT_FOCUS_BAND && (Random() % 100) < param)
      {
          RecordItemEffectBattle(gBattlerTarget, holdEffect);
          gSpecialStatuses[gBattlerTarget].focusBanded = 1;
      }
      if (!(gBattleMons[gBattlerTarget].status2 & STATUS2_SUBSTITUTE)
       && (gBattleMoves[gCurrentMove].effect == EFFECT_FALSE_SWIPE || gProtectStructs[gBattlerTarget].endured || gSpecialStatuses[gBattlerTarget].focusBanded)
       && gBattleMons[gBattlerTarget].hp <= gBattleMoveDamage)
      {
          gBattleMoveDamage = gBattleMons[gBattlerTarget].hp - 1;
          if (gProtectStructs[gBattlerTarget].endured)
          {
              gMoveResultFlags |= MOVE_RESULT_FOE_ENDURED;
          }
          else if (gSpecialStatuses[gBattlerTarget].focusBanded)
          {
              gMoveResultFlags |= MOVE_RESULT_FOE_HUNG_ON;
              gLastUsedItem = gBattleMons[gBattlerTarget].item;
          }
      }
      gBattlescriptCurrInstr++;
}

