/** static void Cmd_attackanimation(void) */
export function Cmd_attackanimation(): any {
  if (gBattleControllerExecFlags)
          return;

      if ((gHitMarker & HITMARKER_NO_ANIMATIONS) && (gCurrentMove != MOVE_TRANSFORM && gCurrentMove != MOVE_SUBSTITUTE))
      {
          BattleScriptPush(gBattlescriptCurrInstr + 1);
          gBattlescriptCurrInstr = BattleScript_Pausex20;
          gBattleScripting.animTurn++;
          gBattleScripting.animTargetsHit++;
      }
      else
      {
          if ((gBattleMoves[gCurrentMove].target & MOVE_TARGET_BOTH
              || gBattleMoves[gCurrentMove].target & MOVE_TARGET_FOES_AND_ALLY
              || gBattleMoves[gCurrentMove].target & MOVE_TARGET_DEPENDS)
              && gBattleScripting.animTargetsHit)
          {
              gBattlescriptCurrInstr++;
              return;
          }
          if (!(gMoveResultFlags & MOVE_RESULT_NO_EFFECT))
          {
              let multihit: any = null;

              gActiveBattler = gBattlerAttacker;

              if (gBattleMons[gBattlerTarget].status2 & STATUS2_SUBSTITUTE)
              {
                  multihit = gMultiHitCounter;
              }
              else if (gMultiHitCounter != 0 && gMultiHitCounter != 1)
              {
                  if (gBattleMons[gBattlerTarget].hp <= gBattleMoveDamage)
                      multihit = 1;
                  else
                      multihit = gMultiHitCounter;
              }
              else
              {
                  multihit = gMultiHitCounter;
              }

              BtlController_EmitMoveAnimation(B_COMM_TO_CONTROLLER, gCurrentMove, gBattleScripting.animTurn, gBattleMovePower, gBattleMoveDamage, gBattleMons[gBattlerAttacker].friendship,gDisableStructs[gBattlerAttacker], multihit);
              gBattleScripting.animTurn++;
              gBattleScripting.animTargetsHit++;
              MarkBattlerForControllerExec(gBattlerAttacker);
              gBattlescriptCurrInstr++;
          }
          else
          {
              BattleScriptPush(gBattlescriptCurrInstr + 1);
              gBattlescriptCurrInstr = BattleScript_Pausex20;
          }
      }
}

/** static void Cmd_waitanimation(void) */
export function Cmd_waitanimation(): any {
  if (gBattleControllerExecFlags == 0)
          gBattlescriptCurrInstr++;
}

/** static void Cmd_healthbarupdate(void) */
export function Cmd_healthbarupdate(): any {
  if (gBattleControllerExecFlags)
          return;

      if (!(gMoveResultFlags & MOVE_RESULT_NO_EFFECT))
      {
          gActiveBattler = GetBattlerForBattleScript(gBattlescriptCurrInstr[1]);

          if (gBattleMons[gActiveBattler].status2 & STATUS2_SUBSTITUTE && gDisableStructs[gActiveBattler].substituteHP && !(gHitMarker & HITMARKER_IGNORE_SUBSTITUTE))
          {
              PrepareStringBattle(STRINGID_SUBSTITUTEDAMAGED, gActiveBattler);
          }
          else
          {
              let healthValue: any = null;

              let currDmg: any = gBattleMoveDamage;
              let maxPossibleDmgValue: any = 10000;  

              if (currDmg <= maxPossibleDmgValue)
                  healthValue = currDmg;
              else
                  healthValue = maxPossibleDmgValue;

              BtlController_EmitHealthBarUpdate(B_COMM_TO_CONTROLLER, healthValue);
              MarkBattlerForControllerExec(gActiveBattler);

              if (GetBattlerSide(gActiveBattler) == B_SIDE_PLAYER && gBattleMoveDamage > 0)
                  gBattleResults.playerMonWasDamaged = TRUE;
          }
      }

      gBattlescriptCurrInstr += 2;
}

/** static void Cmd_datahpupdate(void) */
export function Cmd_datahpupdate(): any {
  let moveType: any = null;

      if (gBattleControllerExecFlags)
          return;

       
       
       
       
      if (gBattleStruct.dynamicMoveType == 0)
          moveType = gBattleMoves[gCurrentMove].type;
      else if (!(gBattleStruct.dynamicMoveType & F_DYNAMIC_TYPE_IGNORE_PHYSICALITY))
          moveType = gBattleStruct.dynamicMoveType & DYNAMIC_TYPE_MASK;
      else
          moveType = gBattleMoves[gCurrentMove].type;

      if (!(gMoveResultFlags & MOVE_RESULT_NO_EFFECT))
      {
          gActiveBattler = GetBattlerForBattleScript(gBattlescriptCurrInstr[1]);
          if (gBattleMons[gActiveBattler].status2 & STATUS2_SUBSTITUTE && gDisableStructs[gActiveBattler].substituteHP && !(gHitMarker & HITMARKER_IGNORE_SUBSTITUTE))
          {
               
              if (gDisableStructs[gActiveBattler].substituteHP >= gBattleMoveDamage)
              {
                  if (gSpecialStatuses[gActiveBattler].shellBellDmg == 0)
                      gSpecialStatuses[gActiveBattler].shellBellDmg = gBattleMoveDamage;
                  gDisableStructs[gActiveBattler].substituteHP -= gBattleMoveDamage;
                  gHpDealt = gBattleMoveDamage;
              }
              else
              {
                   
                  if (gSpecialStatuses[gActiveBattler].shellBellDmg == 0)
                      gSpecialStatuses[gActiveBattler].shellBellDmg = gDisableStructs[gActiveBattler].substituteHP;
                  gHpDealt = gDisableStructs[gActiveBattler].substituteHP;
                  gDisableStructs[gActiveBattler].substituteHP = 0;
              }

              if (gDisableStructs[gActiveBattler].substituteHP == 0)
              {
                   
                  gBattlescriptCurrInstr += 2;
                  BattleScriptPushCursor();
                  gBattlescriptCurrInstr = BattleScript_SubstituteFade;
                  return;
              }
          }
          else
          {
              gHitMarker &= ~HITMARKER_IGNORE_SUBSTITUTE;
              if (gBattleMoveDamage < 0)
              {
                   
                  gBattleMons[gActiveBattler].hp += -gBattleMoveDamage;
                  if (gBattleMons[gActiveBattler].hp > gBattleMons[gActiveBattler].maxHP)
                      gBattleMons[gActiveBattler].hp = gBattleMons[gActiveBattler].maxHP;
              }
              else
              {
                  if (gHitMarker & HITMARKER_IGNORE_BIDE)
                  {
                      gHitMarker &= ~HITMARKER_IGNORE_BIDE;
                  }
                  else
                  {
                       
                      gBideDmg[gActiveBattler] += gBattleMoveDamage;
                      if (gBattlescriptCurrInstr[1] == BS_TARGET)
                          gBideTarget[gActiveBattler] = gBattlerAttacker;
                      else
                          gBideTarget[gActiveBattler] = gBattlerTarget;
                  }

                   
                  if (gBattleMons[gActiveBattler].hp > gBattleMoveDamage)
                  {
                      gBattleMons[gActiveBattler].hp -= gBattleMoveDamage;
                      gHpDealt = gBattleMoveDamage;
                  }
                  else
                  {
                      gHpDealt = gBattleMons[gActiveBattler].hp;
                      gBattleMons[gActiveBattler].hp = 0;
                  }

                   
                  if (gSpecialStatuses[gActiveBattler].shellBellDmg == 0 && !(gHitMarker & HITMARKER_PASSIVE_HP_UPDATE))
                      gSpecialStatuses[gActiveBattler].shellBellDmg = gHpDealt;

                   
                   
                   
                  if (IS_TYPE_PHYSICAL(moveType) && !(gHitMarker & HITMARKER_PASSIVE_HP_UPDATE) && gCurrentMove != MOVE_PAIN_SPLIT)
                  {
                       
                      gProtectStructs[gActiveBattler].physicalDmg = gHpDealt;
                      gSpecialStatuses[gActiveBattler].physicalDmg = gHpDealt;
                      if (gBattlescriptCurrInstr[1] == BS_TARGET)
                      {
                          gProtectStructs[gActiveBattler].physicalBattlerId = gBattlerAttacker;
                          gSpecialStatuses[gActiveBattler].physicalBattlerId = gBattlerAttacker;
                      }
                      else
                      {
                          gProtectStructs[gActiveBattler].physicalBattlerId = gBattlerTarget;
                          gSpecialStatuses[gActiveBattler].physicalBattlerId = gBattlerTarget;
                      }
                  }
                  else if (!IS_TYPE_PHYSICAL(moveType) && !(gHitMarker & HITMARKER_PASSIVE_HP_UPDATE))
                  {
                       
                      gProtectStructs[gActiveBattler].specialDmg = gHpDealt;
                      gSpecialStatuses[gActiveBattler].specialDmg = gHpDealt;
                      if (gBattlescriptCurrInstr[1] == BS_TARGET)
                      {
                          gProtectStructs[gActiveBattler].specialBattlerId = gBattlerAttacker;
                          gSpecialStatuses[gActiveBattler].specialBattlerId = gBattlerAttacker;
                      }
                      else
                      {
                          gProtectStructs[gActiveBattler].specialBattlerId = gBattlerTarget;
                          gSpecialStatuses[gActiveBattler].specialBattlerId = gBattlerTarget;
                      }
                  }
              }
              gHitMarker &= ~HITMARKER_PASSIVE_HP_UPDATE;

               
              BtlController_EmitSetMonData(B_COMM_TO_CONTROLLER, REQUEST_HP_BATTLE, 0, sizeof(gBattleMons[gActiveBattler].hp),gBattleMons[gActiveBattler].hp);
              MarkBattlerForControllerExec(gActiveBattler);
          }
      }
      else
      {
           
          gActiveBattler = GetBattlerForBattleScript(gBattlescriptCurrInstr[1]);
          if (gSpecialStatuses[gActiveBattler].shellBellDmg == 0)
              gSpecialStatuses[gActiveBattler].shellBellDmg = IGNORE_SHELL_BELL;
      }
      gBattlescriptCurrInstr += 2;
}

/** static void Cmd_critmessage(void) */
export function Cmd_critmessage(): any {
  if (gBattleControllerExecFlags == 0)
      {
          if (gCritMultiplier == 2 && !(gMoveResultFlags & MOVE_RESULT_NO_EFFECT))
          {
              PrepareStringBattle(STRINGID_CRITICALHIT, gBattlerAttacker);
              gBattleCommunication[MSG_DISPLAY] = 1;
          }
          gBattlescriptCurrInstr++;
      }
}

/** static void Cmd_effectivenesssound(void) */
export function Cmd_effectivenesssound(): any {
  if (gBattleControllerExecFlags)
          return;

      gActiveBattler = gBattlerTarget;
      if (!(gMoveResultFlags & MOVE_RESULT_MISSED))
      {
          switch (gMoveResultFlags & (~MOVE_RESULT_MISSED))
          {
          case MOVE_RESULT_SUPER_EFFECTIVE:
              BtlController_EmitPlaySE(B_COMM_TO_CONTROLLER, SE_SUPER_EFFECTIVE);
              MarkBattlerForControllerExec(gActiveBattler);
              break;
          case MOVE_RESULT_NOT_VERY_EFFECTIVE:
              BtlController_EmitPlaySE(B_COMM_TO_CONTROLLER, SE_NOT_EFFECTIVE);
              MarkBattlerForControllerExec(gActiveBattler);
              break;
          case MOVE_RESULT_DOESNT_AFFECT_FOE:
          case MOVE_RESULT_FAILED:
               
              break;
          case MOVE_RESULT_FOE_ENDURED:
          case MOVE_RESULT_ONE_HIT_KO:
          case MOVE_RESULT_FOE_HUNG_ON:
          default:
              if (gMoveResultFlags & MOVE_RESULT_SUPER_EFFECTIVE)
              {
                  BtlController_EmitPlaySE(B_COMM_TO_CONTROLLER, SE_SUPER_EFFECTIVE);
                  MarkBattlerForControllerExec(gActiveBattler);
              }
              else if (gMoveResultFlags & MOVE_RESULT_NOT_VERY_EFFECTIVE)
              {
                  BtlController_EmitPlaySE(B_COMM_TO_CONTROLLER, SE_NOT_EFFECTIVE);
                  MarkBattlerForControllerExec(gActiveBattler);
              }
              else if (!(gMoveResultFlags & (MOVE_RESULT_DOESNT_AFFECT_FOE | MOVE_RESULT_FAILED)))
              {
                  BtlController_EmitPlaySE(B_COMM_TO_CONTROLLER, SE_EFFECTIVE);
                  MarkBattlerForControllerExec(gActiveBattler);
              }
              break;
          }
      }
      gBattlescriptCurrInstr++;
}

/** static void Cmd_resultmessage(void) */
export function Cmd_resultmessage(): any {
  let stringId: any = 0;

      if (gBattleControllerExecFlags)
          return;

      if (gMoveResultFlags & MOVE_RESULT_MISSED && (!(gMoveResultFlags & MOVE_RESULT_DOESNT_AFFECT_FOE) || gBattleCommunication[MISS_TYPE] > B_MSG_AVOIDED_ATK))
      {
          stringId = gMissStringIds[gBattleCommunication[MISS_TYPE]];
          gBattleCommunication[MSG_DISPLAY] = 1;
      }
      else
      {
          gBattleCommunication[MSG_DISPLAY] = 1;
          switch (gMoveResultFlags & (~MOVE_RESULT_MISSED))
          {
          case MOVE_RESULT_SUPER_EFFECTIVE:
              stringId = STRINGID_SUPEREFFECTIVE;
              break;
          case MOVE_RESULT_NOT_VERY_EFFECTIVE:
              stringId = STRINGID_NOTVERYEFFECTIVE;
              break;
          case MOVE_RESULT_ONE_HIT_KO:
              stringId = STRINGID_ONEHITKO;
              break;
          case MOVE_RESULT_FOE_ENDURED:
              stringId = STRINGID_PKMNENDUREDHIT;
              break;
          case MOVE_RESULT_FAILED:
              stringId = STRINGID_BUTITFAILED;
              break;
          case MOVE_RESULT_DOESNT_AFFECT_FOE:
              stringId = STRINGID_ITDOESNTAFFECT;
              break;
          case MOVE_RESULT_FOE_HUNG_ON:
              gLastUsedItem = gBattleMons[gBattlerTarget].item;
              gPotentialItemEffectBattler = gBattlerTarget;
              gMoveResultFlags &= ~(MOVE_RESULT_FOE_ENDURED | MOVE_RESULT_FOE_HUNG_ON);
              BattleScriptPushCursor();
              gBattlescriptCurrInstr = BattleScript_FocusBandActivates;
              return;
          default:
              if (gMoveResultFlags & MOVE_RESULT_DOESNT_AFFECT_FOE)
              {
                  stringId = STRINGID_ITDOESNTAFFECT;
              }
              else if (gMoveResultFlags & MOVE_RESULT_ONE_HIT_KO)
              {
                  gMoveResultFlags &= ~MOVE_RESULT_ONE_HIT_KO;
                  gMoveResultFlags &= ~MOVE_RESULT_SUPER_EFFECTIVE;
                  gMoveResultFlags &= ~MOVE_RESULT_NOT_VERY_EFFECTIVE;
                  BattleScriptPushCursor();
                  gBattlescriptCurrInstr = BattleScript_OneHitKOMsg;
                  return;
              }
              else if (gMoveResultFlags & MOVE_RESULT_FOE_ENDURED)
              {
                  gMoveResultFlags &= ~(MOVE_RESULT_FOE_ENDURED | MOVE_RESULT_FOE_HUNG_ON);
                  BattleScriptPushCursor();
                  gBattlescriptCurrInstr = BattleScript_EnduredMsg;
                  return;
              }
              else if (gMoveResultFlags & MOVE_RESULT_FOE_HUNG_ON)
              {
                  gLastUsedItem = gBattleMons[gBattlerTarget].item;
                  gPotentialItemEffectBattler = gBattlerTarget;
                  gMoveResultFlags &= ~(MOVE_RESULT_FOE_ENDURED | MOVE_RESULT_FOE_HUNG_ON);
                  BattleScriptPushCursor();
                  gBattlescriptCurrInstr = BattleScript_FocusBandActivates;
                  return;
              }
              else if (gMoveResultFlags & MOVE_RESULT_FAILED)
              {
                  stringId = STRINGID_BUTITFAILED;
              }
              else
              {
                  gBattleCommunication[MSG_DISPLAY] = 0;
              }
          }
      }

      if (stringId)
          PrepareStringBattle(stringId, gBattlerAttacker);

      gBattlescriptCurrInstr++;
}

/** static void Cmd_printstring(void) */
export function Cmd_printstring(): any {
  if (gBattleControllerExecFlags == 0)
      {
          let _var: any = T2_READ_16(gBattlescriptCurrInstr + 1);
          PrepareStringBattle(_var, gBattlerAttacker);
          gBattlescriptCurrInstr += 3;
          gBattleCommunication[MSG_DISPLAY] = 1;
      }
}

/** static void Cmd_printselectionstring(void) */
export function Cmd_printselectionstring(): any {
  gActiveBattler = gBattlerAttacker;

      BtlController_EmitPrintSelectionString(B_COMM_TO_CONTROLLER, T2_READ_16(gBattlescriptCurrInstr + 1));
      MarkBattlerForControllerExec(gActiveBattler);

      gBattlescriptCurrInstr += 3;
      gBattleCommunication[MSG_DISPLAY] = 1;
}

/** static void Cmd_waitmessage(void) */
export function Cmd_waitmessage(): any {
  if (gBattleControllerExecFlags == 0)
      {
          if (!gBattleCommunication[MSG_DISPLAY])
          {
              gBattlescriptCurrInstr += 3;
          }
          else
          {
              let toWait: any = T2_READ_16(gBattlescriptCurrInstr + 1);
              if (++gPauseCounterBattle >= toWait)
              {
                  gPauseCounterBattle = 0;
                  gBattlescriptCurrInstr += 3;
                  gBattleCommunication[MSG_DISPLAY] = 0;
              }
          }
      }
}

/** static void Cmd_printfromtable(void) */
export function Cmd_printfromtable(): any {
  if (gBattleControllerExecFlags == 0)
      {
          let ptr: any = T1_READ_PTR(gBattlescriptCurrInstr + 1);
          ptr += gBattleCommunication[MULTISTRING_CHOOSER];

          PrepareStringBattle(ptr, gBattlerAttacker);

          gBattlescriptCurrInstr += 5;
          gBattleCommunication[MSG_DISPLAY] = 1;
      }
}

/** static void Cmd_printselectionstringfromtable(void) */
export function Cmd_printselectionstringfromtable(): any {
  if (gBattleControllerExecFlags == 0)
      {
          let ptr: any = T1_READ_PTR(gBattlescriptCurrInstr + 1);
          ptr += gBattleCommunication[MULTISTRING_CHOOSER];

          gActiveBattler = gBattlerAttacker;
          BtlController_EmitPrintSelectionString(B_COMM_TO_CONTROLLER, ptr);
          MarkBattlerForControllerExec(gActiveBattler);

          gBattlescriptCurrInstr += 5;
          gBattleCommunication[MSG_DISPLAY] = 1;
      }
}

/** u8 GetBattlerTurnOrderNum(u8 battler) */
export function GetBattlerTurnOrderNum(battler: any): any {
  let i: any = null;
      for (i = 0; i < gBattlersCount; i++)
      {
          if (gBattlerByTurnOrder[i] == battler)
              break;
      }
      return i;
}

/** void SetMoveEffect(bool8 primary, u8 certain) */
export function SetMoveEffect(primary: any, certain: any): any {
  let statusChanged: any = FALSE;
      let affectsUser: any = 0;  
      let noSunCanFreeze: any = TRUE;

      if (gBattleCommunication[MOVE_EFFECT_BYTE] & MOVE_EFFECT_AFFECTS_USER)
      {
          gEffectBattler = gBattlerAttacker;  
          gBattleCommunication[MOVE_EFFECT_BYTE] &= ~MOVE_EFFECT_AFFECTS_USER;
          affectsUser = MOVE_EFFECT_AFFECTS_USER;
          gBattleScripting.battler = gBattlerTarget;  
      }
      else
      {
          gEffectBattler = gBattlerTarget;
          gBattleScripting.battler = gBattlerAttacker;
      }

      if (gBattleMons[gEffectBattler].ability == ABILITY_SHIELD_DUST && !(gHitMarker & HITMARKER_STATUS_ABILITY_EFFECT)
          && !primary && gBattleCommunication[MOVE_EFFECT_BYTE] <= 9)
          INCREMENT_RESET_RETURN

      if (gSideStatuses[GET_BATTLER_SIDE(gEffectBattler)] & SIDE_STATUS_SAFEGUARD && !(gHitMarker & HITMARKER_STATUS_ABILITY_EFFECT)
          && !primary && gBattleCommunication[MOVE_EFFECT_BYTE] <= 7)
          INCREMENT_RESET_RETURN

      if (gBattleMons[gEffectBattler].hp == 0
          && gBattleCommunication[MOVE_EFFECT_BYTE] != MOVE_EFFECT_PAYDAY
          && gBattleCommunication[MOVE_EFFECT_BYTE] != MOVE_EFFECT_STEAL_ITEM)
          INCREMENT_RESET_RETURN

      if (gBattleMons[gEffectBattler].status2 & STATUS2_SUBSTITUTE && affectsUser != MOVE_EFFECT_AFFECTS_USER)
          INCREMENT_RESET_RETURN

      if (gBattleCommunication[MOVE_EFFECT_BYTE] <= PRIMARY_STATUS_MOVE_EFFECT)
      {
          switch (sStatusFlagsForMoveEffects[gBattleCommunication[MOVE_EFFECT_BYTE]])
          {
          case STATUS1_SLEEP:
               
              if (gBattleMons[gEffectBattler].ability != ABILITY_SOUNDPROOF)
              {
                  for (gActiveBattler = 0;
                      gActiveBattler < gBattlersCount && !(gBattleMons[gActiveBattler].status2 & STATUS2_UPROAR);
                      gActiveBattler++)
                  {}
              }
              else
              {
                  gActiveBattler = gBattlersCount;
              }

              if (gBattleMons[gEffectBattler].status1)
                  break;
              if (gActiveBattler != gBattlersCount)
                  break;
              if (gBattleMons[gEffectBattler].ability == ABILITY_VITAL_SPIRIT)
                  break;
              if (gBattleMons[gEffectBattler].ability == ABILITY_INSOMNIA)
                  break;

              CancelMultiTurnMoves(gEffectBattler);
              statusChanged = TRUE;
              break;
          case STATUS1_POISON:
              if (gBattleMons[gEffectBattler].ability == ABILITY_IMMUNITY
                  && (primary == TRUE || certain == MOVE_EFFECT_CERTAIN))
              {
                  gLastUsedAbility = ABILITY_IMMUNITY;
                  RecordAbilityBattle(gEffectBattler, ABILITY_IMMUNITY);

                  BattleScriptPush(gBattlescriptCurrInstr + 1);
                  gBattlescriptCurrInstr = BattleScript_PSNPrevention;

                  if (gHitMarker & HITMARKER_STATUS_ABILITY_EFFECT)
                  {
                      gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_ABILITY_PREVENTS_ABILITY_STATUS;
                      gHitMarker &= ~HITMARKER_STATUS_ABILITY_EFFECT;
                  }
                  else
                  {
                      gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_ABILITY_PREVENTS_MOVE_STATUS;
                  }
                  RESET_RETURN
              }
              if ((IS_BATTLER_OF_TYPE(gEffectBattler, TYPE_POISON) || IS_BATTLER_OF_TYPE(gEffectBattler, TYPE_STEEL))
                  && (gHitMarker & HITMARKER_STATUS_ABILITY_EFFECT)
                  && (primary == TRUE || certain == MOVE_EFFECT_CERTAIN))
              {
                  BattleScriptPush(gBattlescriptCurrInstr + 1);
                  gBattlescriptCurrInstr = BattleScript_PSNPrevention;

                  gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_STATUS_HAD_NO_EFFECT;
                  RESET_RETURN
              }
              if (IS_BATTLER_OF_TYPE(gEffectBattler, TYPE_POISON))
                  break;
              if (IS_BATTLER_OF_TYPE(gEffectBattler, TYPE_STEEL))
                  break;
              if (gBattleMons[gEffectBattler].status1)
                  break;
              if (gBattleMons[gEffectBattler].ability == ABILITY_IMMUNITY)
                  break;

              statusChanged = TRUE;
              break;
          case STATUS1_BURN:
              if (gBattleMons[gEffectBattler].ability == ABILITY_WATER_VEIL
                  && (primary == TRUE || certain == MOVE_EFFECT_CERTAIN))
              {
                  gLastUsedAbility = ABILITY_WATER_VEIL;
                  RecordAbilityBattle(gEffectBattler, ABILITY_WATER_VEIL);

                  BattleScriptPush(gBattlescriptCurrInstr + 1);
                  gBattlescriptCurrInstr = BattleScript_BRNPrevention;
                  if (gHitMarker & HITMARKER_STATUS_ABILITY_EFFECT)
                  {
                      gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_ABILITY_PREVENTS_ABILITY_STATUS;
                      gHitMarker &= ~HITMARKER_STATUS_ABILITY_EFFECT;
                  }
                  else
                  {
                      gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_ABILITY_PREVENTS_MOVE_STATUS;
                  }
                  RESET_RETURN
              }
              if (IS_BATTLER_OF_TYPE(gEffectBattler, TYPE_FIRE)
                  && (gHitMarker & HITMARKER_STATUS_ABILITY_EFFECT)
                  && (primary == TRUE || certain == MOVE_EFFECT_CERTAIN))
              {
                  BattleScriptPush(gBattlescriptCurrInstr + 1);
                  gBattlescriptCurrInstr = BattleScript_BRNPrevention;

                  gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_STATUS_HAD_NO_EFFECT;
                  RESET_RETURN
              }
              if (IS_BATTLER_OF_TYPE(gEffectBattler, TYPE_FIRE))
                  break;
              if (gBattleMons[gEffectBattler].ability == ABILITY_WATER_VEIL)
                  break;
              if (gBattleMons[gEffectBattler].status1)
                  break;

              statusChanged = TRUE;
              break;
          case STATUS1_FREEZE:
              if (WEATHER_HAS_EFFECT && gBattleWeather & B_WEATHER_SUN)
                  noSunCanFreeze = FALSE;
              if (IS_BATTLER_OF_TYPE(gEffectBattler, TYPE_ICE))
                  break;
              if (gBattleMons[gEffectBattler].status1)
                  break;
              if (noSunCanFreeze == FALSE)
                  break;
              if (gBattleMons[gEffectBattler].ability == ABILITY_MAGMA_ARMOR)
                  break;

              CancelMultiTurnMoves(gEffectBattler);
              statusChanged = TRUE;
              break;
          case STATUS1_PARALYSIS:
              if (gBattleMons[gEffectBattler].ability == ABILITY_LIMBER)
              {
                  if (primary == TRUE || certain == MOVE_EFFECT_CERTAIN)
                  {
                      gLastUsedAbility = ABILITY_LIMBER;
                      RecordAbilityBattle(gEffectBattler, ABILITY_LIMBER);

                      BattleScriptPush(gBattlescriptCurrInstr + 1);
                      gBattlescriptCurrInstr = BattleScript_PRLZPrevention;

                      if (gHitMarker & HITMARKER_STATUS_ABILITY_EFFECT)
                      {
                          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_ABILITY_PREVENTS_ABILITY_STATUS;
                          gHitMarker &= ~HITMARKER_STATUS_ABILITY_EFFECT;
                      }
                      else
                      {
                          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_ABILITY_PREVENTS_MOVE_STATUS;
                      }
                      RESET_RETURN
                  }
                  else
                  {
                      break;
                  }
              }
              if (gBattleMons[gEffectBattler].status1)
                  break;

              statusChanged = TRUE;
              break;
          case STATUS1_TOXIC_POISON:
              if (gBattleMons[gEffectBattler].ability == ABILITY_IMMUNITY && (primary == TRUE || certain == MOVE_EFFECT_CERTAIN))
              {
                  gLastUsedAbility = ABILITY_IMMUNITY;
                  RecordAbilityBattle(gEffectBattler, ABILITY_IMMUNITY);

                  BattleScriptPush(gBattlescriptCurrInstr + 1);
                  gBattlescriptCurrInstr = BattleScript_PSNPrevention;

                  if (gHitMarker & HITMARKER_STATUS_ABILITY_EFFECT)
                  {
                      gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_ABILITY_PREVENTS_ABILITY_STATUS;
                      gHitMarker &= ~HITMARKER_STATUS_ABILITY_EFFECT;
                  }
                  else
                  {
                      gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_ABILITY_PREVENTS_MOVE_STATUS;
                  }
                  RESET_RETURN
              }
              if ((IS_BATTLER_OF_TYPE(gEffectBattler, TYPE_POISON) || IS_BATTLER_OF_TYPE(gEffectBattler, TYPE_STEEL))
                  && (gHitMarker & HITMARKER_STATUS_ABILITY_EFFECT)
                  && (primary == TRUE || certain == MOVE_EFFECT_CERTAIN))
              {
                  BattleScriptPush(gBattlescriptCurrInstr + 1);
                  gBattlescriptCurrInstr = BattleScript_PSNPrevention;

                  gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_STATUS_HAD_NO_EFFECT;
                  RESET_RETURN
              }
              if (gBattleMons[gEffectBattler].status1)
                  break;
              if (!IS_BATTLER_OF_TYPE(gEffectBattler, TYPE_POISON) && !IS_BATTLER_OF_TYPE(gEffectBattler, TYPE_STEEL))
              {
                  if (gBattleMons[gEffectBattler].ability == ABILITY_IMMUNITY)
                      break;

                   
                  gBattleMons[gEffectBattler].status1 &= ~STATUS1_TOXIC_POISON;
                  gBattleMons[gEffectBattler].status1 &= ~STATUS1_POISON;
                  statusChanged = TRUE;
                  break;
              }
              else
              {
                  gMoveResultFlags |= MOVE_RESULT_DOESNT_AFFECT_FOE;
              }
              break;
          }
          if (statusChanged == TRUE)
          {
              BattleScriptPush(gBattlescriptCurrInstr + 1);

              if (sStatusFlagsForMoveEffects[gBattleCommunication[MOVE_EFFECT_BYTE]] == STATUS1_SLEEP)
                  gBattleMons[gEffectBattler].status1 |= STATUS1_SLEEP_TURN((Random() & 3) + 2);  
              else
                  gBattleMons[gEffectBattler].status1 |= sStatusFlagsForMoveEffects[gBattleCommunication[MOVE_EFFECT_BYTE]];

              gBattlescriptCurrInstr = sMoveEffectBS_Ptrs[gBattleCommunication[MOVE_EFFECT_BYTE]];

              gActiveBattler = gEffectBattler;
              BtlController_EmitSetMonData(B_COMM_TO_CONTROLLER, REQUEST_STATUS_BATTLE, 0, sizeof(gBattleMons[gEffectBattler].status1),gBattleMons[gEffectBattler].status1);
              MarkBattlerForControllerExec(gActiveBattler);

              if (gHitMarker & HITMARKER_STATUS_ABILITY_EFFECT)
              {
                  gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_STATUSED_BY_ABILITY;
                  gHitMarker &= ~HITMARKER_STATUS_ABILITY_EFFECT;
              }
              else
              {
                  gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_STATUSED;
              }

               

              if (gBattleCommunication[MOVE_EFFECT_BYTE] == MOVE_EFFECT_POISON
               || gBattleCommunication[MOVE_EFFECT_BYTE] == MOVE_EFFECT_TOXIC
               || gBattleCommunication[MOVE_EFFECT_BYTE] == MOVE_EFFECT_PARALYSIS
               || gBattleCommunication[MOVE_EFFECT_BYTE] == MOVE_EFFECT_BURN)
               {
                  let synchronizeEffect: any =gBattleStruct.synchronizeMoveEffect;
                  synchronizeEffect = gBattleCommunication[MOVE_EFFECT_BYTE];
                  gHitMarker |= HITMARKER_SYNCHRONIZE_EFFECT;
               }
              return;
          }
          else if (statusChanged == FALSE)
          {
              gBattleCommunication[MOVE_EFFECT_BYTE] = 0;
              gBattlescriptCurrInstr++;
              return;
          }
          return;
      }
      else
      {
          if (gBattleMons[gEffectBattler].status2 & sStatusFlagsForMoveEffects[gBattleCommunication[MOVE_EFFECT_BYTE]])
          {
              gBattlescriptCurrInstr++;
          }
          else
          {
              let side: any = null;
              switch (gBattleCommunication[MOVE_EFFECT_BYTE])
              {
              case MOVE_EFFECT_CONFUSION:
                  if (gBattleMons[gEffectBattler].ability == ABILITY_OWN_TEMPO
                      || gBattleMons[gEffectBattler].status2 & STATUS2_CONFUSION)
                  {
                      gBattlescriptCurrInstr++;
                  }
                  else
                  {
                      gBattleMons[gEffectBattler].status2 |= STATUS2_CONFUSION_TURN(((Random()) % 4) + 2);  

                      BattleScriptPush(gBattlescriptCurrInstr + 1);
                      gBattlescriptCurrInstr = sMoveEffectBS_Ptrs[gBattleCommunication[MOVE_EFFECT_BYTE]];
                  }
                  break;
              case MOVE_EFFECT_FLINCH:
                  if (gBattleMons[gEffectBattler].ability == ABILITY_INNER_FOCUS)
                  {
                      if (primary == TRUE || certain == MOVE_EFFECT_CERTAIN)
                      {
                          gLastUsedAbility = ABILITY_INNER_FOCUS;
                          RecordAbilityBattle(gEffectBattler, ABILITY_INNER_FOCUS);
                          gBattlescriptCurrInstr = BattleScript_FlinchPrevention;
                      }
                      else
                      {
                          gBattlescriptCurrInstr++;
                      }
                  }
                  else
                  {
                      if (GetBattlerTurnOrderNum(gEffectBattler) > gCurrentTurnActionNumber)
                          gBattleMons[gEffectBattler].status2 |= sStatusFlagsForMoveEffects[gBattleCommunication[MOVE_EFFECT_BYTE]];
                      gBattlescriptCurrInstr++;
                  }
                  break;
              case MOVE_EFFECT_UPROAR:
                  if (!(gBattleMons[gEffectBattler].status2 & STATUS2_UPROAR))
                  {
                      gBattleMons[gEffectBattler].status2 |= STATUS2_MULTIPLETURNS;
                      gLockedMoves[gEffectBattler] = gCurrentMove;
                      gBattleMons[gEffectBattler].status2 |= STATUS2_UPROAR_TURN((Random() & 3) + 2);  

                      BattleScriptPush(gBattlescriptCurrInstr + 1);
                      gBattlescriptCurrInstr = sMoveEffectBS_Ptrs[gBattleCommunication[MOVE_EFFECT_BYTE]];
                  }
                  else
                  {
                      gBattlescriptCurrInstr++;
                  }
                  break;
              case MOVE_EFFECT_PAYDAY:
                  if (GET_BATTLER_SIDE(gBattlerAttacker) == B_SIDE_PLAYER)
                  {
                      let payday: any = gPaydayMoney;
                      gPaydayMoney += (gBattleMons[gBattlerAttacker].level * 5);
                      if (payday > gPaydayMoney)
                          gPaydayMoney = 0xFFFF;
                  }
                  BattleScriptPush(gBattlescriptCurrInstr + 1);
                  gBattlescriptCurrInstr = sMoveEffectBS_Ptrs[gBattleCommunication[MOVE_EFFECT_BYTE]];
                  break;
              case MOVE_EFFECT_TRI_ATTACK:
                  if (gBattleMons[gEffectBattler].status1)
                  {
                      gBattlescriptCurrInstr++;
                  }
                  else
                  {
                      gBattleCommunication[MOVE_EFFECT_BYTE] = Random() % 3 + 3;
                      SetMoveEffect(FALSE, 0);
                  }
                  break;
              case MOVE_EFFECT_CHARGING:
                  gBattleMons[gEffectBattler].status2 |= STATUS2_MULTIPLETURNS;
                  gLockedMoves[gEffectBattler] = gCurrentMove;
                  gProtectStructs[gEffectBattler].chargingTurn = 1;
                  gBattlescriptCurrInstr++;
                  break;
              case MOVE_EFFECT_WRAP:
                  if (gBattleMons[gEffectBattler].status2 & STATUS2_WRAPPED)
                  {
                      gBattlescriptCurrInstr++;
                  }
                  else
                  {
                      gBattleMons[gEffectBattler].status2 |= STATUS2_WRAPPED_TURN((Random() & 3) + 3);  

                      MEM_WRITE((gBattleStruct.wrappedMove + gEffectBattler * 2 + 0), gCurrentMove);
                      MEM_WRITE((gBattleStruct.wrappedMove + gEffectBattler * 2 + 1), gCurrentMove >> 8);
                      MEM_WRITE((gBattleStruct.wrappedBy + gEffectBattler), gBattlerAttacker);

                      BattleScriptPush(gBattlescriptCurrInstr + 1);
                      gBattlescriptCurrInstr = sMoveEffectBS_Ptrs[gBattleCommunication[MOVE_EFFECT_BYTE]];

                      for (gBattleCommunication[MULTISTRING_CHOOSER] = 0; ; gBattleCommunication[MULTISTRING_CHOOSER]++)
                      {
                          if (gBattleCommunication[MULTISTRING_CHOOSER] >= NUM_TRAPPING_MOVES - 1)
                              break;
                          if (gTrappingMoves[gBattleCommunication[MULTISTRING_CHOOSER]] == gCurrentMove)
                              break;
                      }
                  }
                  break;
              case MOVE_EFFECT_RECOIL_25:  
                  gBattleMoveDamage = (gHpDealt) / 4;
                  if (gBattleMoveDamage == 0)
                      gBattleMoveDamage = 1;

                  BattleScriptPush(gBattlescriptCurrInstr + 1);
                  gBattlescriptCurrInstr = sMoveEffectBS_Ptrs[gBattleCommunication[MOVE_EFFECT_BYTE]];
                  break;
              case MOVE_EFFECT_ATK_PLUS_1:
              case MOVE_EFFECT_DEF_PLUS_1:
              case MOVE_EFFECT_SPD_PLUS_1:
              case MOVE_EFFECT_SP_ATK_PLUS_1:
              case MOVE_EFFECT_SP_DEF_PLUS_1:
              case MOVE_EFFECT_ACC_PLUS_1:
              case MOVE_EFFECT_EVS_PLUS_1:
                  if (ChangeStatBuffs(SET_STAT_BUFF_VALUE(1),
                                      gBattleCommunication[MOVE_EFFECT_BYTE] - MOVE_EFFECT_ATK_PLUS_1 + 1,
                                      affectsUser, 0))
                  {
                      gBattlescriptCurrInstr++;
                  }
                  else
                  {
                      gBattleScripting.animArg1 = gBattleCommunication[MOVE_EFFECT_BYTE] & ~(MOVE_EFFECT_AFFECTS_USER | MOVE_EFFECT_CERTAIN);
                      gBattleScripting.animArg2 = 0;
                      BattleScriptPush(gBattlescriptCurrInstr + 1);
                      gBattlescriptCurrInstr = BattleScript_StatUp;
                  }
                  break;
              case MOVE_EFFECT_ATK_MINUS_1:
              case MOVE_EFFECT_DEF_MINUS_1:
              case MOVE_EFFECT_SPD_MINUS_1:
              case MOVE_EFFECT_SP_ATK_MINUS_1:
              case MOVE_EFFECT_SP_DEF_MINUS_1:
              case MOVE_EFFECT_ACC_MINUS_1:
              case MOVE_EFFECT_EVS_MINUS_1:
                  if (ChangeStatBuffs(SET_STAT_BUFF_VALUE(1) | STAT_BUFF_NEGATIVE,
                                      gBattleCommunication[MOVE_EFFECT_BYTE] - MOVE_EFFECT_ATK_MINUS_1 + 1,
                                      affectsUser, 0))
                  {
                      gBattlescriptCurrInstr++;
                  }
                  else
                  {
                      gBattleScripting.animArg1 = gBattleCommunication[MOVE_EFFECT_BYTE] & ~(MOVE_EFFECT_AFFECTS_USER | MOVE_EFFECT_CERTAIN);
                      gBattleScripting.animArg2 = 0;
                      BattleScriptPush(gBattlescriptCurrInstr + 1);
                      gBattlescriptCurrInstr = BattleScript_StatDown;
                  }
                  break;
              case MOVE_EFFECT_ATK_PLUS_2:
              case MOVE_EFFECT_DEF_PLUS_2:
              case MOVE_EFFECT_SPD_PLUS_2:
              case MOVE_EFFECT_SP_ATK_PLUS_2:
              case MOVE_EFFECT_SP_DEF_PLUS_2:
              case MOVE_EFFECT_ACC_PLUS_2:
              case MOVE_EFFECT_EVS_PLUS_2:
                  if (ChangeStatBuffs(SET_STAT_BUFF_VALUE(2),
                                      gBattleCommunication[MOVE_EFFECT_BYTE] - MOVE_EFFECT_ATK_PLUS_2 + 1,
                                      affectsUser, 0))
                  {
                      gBattlescriptCurrInstr++;
                  }
                  else
                  {
                      gBattleScripting.animArg1 = gBattleCommunication[MOVE_EFFECT_BYTE] & ~(MOVE_EFFECT_AFFECTS_USER | MOVE_EFFECT_CERTAIN);
                      gBattleScripting.animArg2 = 0;
                      BattleScriptPush(gBattlescriptCurrInstr + 1);
                      gBattlescriptCurrInstr = BattleScript_StatUp;
                  }
                  break;
              case MOVE_EFFECT_ATK_MINUS_2:
              case MOVE_EFFECT_DEF_MINUS_2:
              case MOVE_EFFECT_SPD_MINUS_2:
              case MOVE_EFFECT_SP_ATK_MINUS_2:
              case MOVE_EFFECT_SP_DEF_MINUS_2:
              case MOVE_EFFECT_ACC_MINUS_2:
              case MOVE_EFFECT_EVS_MINUS_2:
                  if (ChangeStatBuffs(SET_STAT_BUFF_VALUE(2) | STAT_BUFF_NEGATIVE,
                                      gBattleCommunication[MOVE_EFFECT_BYTE] - MOVE_EFFECT_ATK_MINUS_2 + 1,
                                      affectsUser, 0))
                  {
                      gBattlescriptCurrInstr++;
                  }
                  else
                  {
                      gBattleScripting.animArg1 = gBattleCommunication[MOVE_EFFECT_BYTE] & ~(MOVE_EFFECT_AFFECTS_USER | MOVE_EFFECT_CERTAIN);
                      gBattleScripting.animArg2 = 0;
                      BattleScriptPush(gBattlescriptCurrInstr + 1);
                      gBattlescriptCurrInstr = BattleScript_StatDown;
                  }
                  break;
              case MOVE_EFFECT_RECHARGE:
                  gBattleMons[gEffectBattler].status2 |= STATUS2_RECHARGE;
                  gDisableStructs[gEffectBattler].rechargeTimer = 2;
                  gLockedMoves[gEffectBattler] = gCurrentMove;
                  gBattlescriptCurrInstr++;
                  break;
              case MOVE_EFFECT_RAGE:
                  gBattleMons[gBattlerAttacker].status2 |= STATUS2_RAGE;
                  gBattlescriptCurrInstr++;
                  break;
              case MOVE_EFFECT_STEAL_ITEM:
                  {
                      if (gBattleTypeFlags & BATTLE_TYPE_TRAINER_HILL)
                      {
                          gBattlescriptCurrInstr++;
                          break;
                      }

                      side = GetBattlerSide(gBattlerAttacker);
                      if (GetBattlerSide(gBattlerAttacker) == B_SIDE_OPPONENT
                          && !(gBattleTypeFlags &
                              (BATTLE_TYPE_EREADER_TRAINER
                              | BATTLE_TYPE_FRONTIER
                              | BATTLE_TYPE_LINK
                              | BATTLE_TYPE_RECORDED_LINK
                              | BATTLE_TYPE_SECRET_BASE)))
                      {
                          gBattlescriptCurrInstr++;
                      }
                      else if (!(gBattleTypeFlags &
                              (BATTLE_TYPE_EREADER_TRAINER
                              | BATTLE_TYPE_FRONTIER
                              | BATTLE_TYPE_LINK
                              | BATTLE_TYPE_RECORDED_LINK
                              | BATTLE_TYPE_SECRET_BASE))
                          && (gWishFutureKnock.knockedOffMons[side] & gBitTable[gBattlerPartyIndexes[gBattlerAttacker]]))
                      {
                          gBattlescriptCurrInstr++;
                      }
                      else if (gBattleMons[gBattlerTarget].item
                          && gBattleMons[gBattlerTarget].ability == ABILITY_STICKY_HOLD)
                      {
                          BattleScriptPushCursor();
                          gBattlescriptCurrInstr = BattleScript_NoItemSteal;

                          gLastUsedAbility = gBattleMons[gBattlerTarget].ability;
                          RecordAbilityBattle(gBattlerTarget, gLastUsedAbility);
                      }
                      else if (gBattleMons[gBattlerAttacker].item != ITEM_NONE
                          || gBattleMons[gBattlerTarget].item == ITEM_ENIGMA_BERRY
                          || IS_ITEM_MAIL(gBattleMons[gBattlerTarget].item)
                          || gBattleMons[gBattlerTarget].item == ITEM_NONE)
                      {
                          gBattlescriptCurrInstr++;
                      }
                      else
                      {
                          let changedItem: any =gBattleStruct.changedItems[gBattlerAttacker];
                          gLastUsedItem = changedItem = gBattleMons[gBattlerTarget].item;
                          gBattleMons[gBattlerTarget].item = ITEM_NONE;

                          gActiveBattler = gBattlerAttacker;
                          BtlController_EmitSetMonData(B_COMM_TO_CONTROLLER, REQUEST_HELDITEM_BATTLE, 0, 0,gLastUsedItem);
                          MarkBattlerForControllerExec(gBattlerAttacker);

                          gActiveBattler = gBattlerTarget;
                          BtlController_EmitSetMonData(B_COMM_TO_CONTROLLER, REQUEST_HELDITEM_BATTLE, 0, sizeof(gBattleMons[gBattlerTarget].item),gBattleMons[gBattlerTarget].item);
                          MarkBattlerForControllerExec(gBattlerTarget);

                          BattleScriptPush(gBattlescriptCurrInstr + 1);
                          gBattlescriptCurrInstr = BattleScript_ItemSteal;

                          ((gBattleStruct.choicedMove[gBattlerTarget]) + 0) = 0;
                          ((gBattleStruct.choicedMove[gBattlerTarget]) + 1) = 0;
                      }
                  }
                  break;
              case MOVE_EFFECT_PREVENT_ESCAPE:
                  gBattleMons[gBattlerTarget].status2 |= STATUS2_ESCAPE_PREVENTION;
                  gDisableStructs[gBattlerTarget].battlerPreventingEscape = gBattlerAttacker;
                  gBattlescriptCurrInstr++;
                  break;
              case MOVE_EFFECT_NIGHTMARE:
                  gBattleMons[gBattlerTarget].status2 |= STATUS2_NIGHTMARE;
                  gBattlescriptCurrInstr++;
                  break;
              case MOVE_EFFECT_ALL_STATS_UP:
                  BattleScriptPush(gBattlescriptCurrInstr + 1);
                  gBattlescriptCurrInstr = BattleScript_AllStatsUp;
                  break;
              case MOVE_EFFECT_RAPIDSPIN:
                  BattleScriptPush(gBattlescriptCurrInstr + 1);
                  gBattlescriptCurrInstr = BattleScript_RapidSpinAway;
                  break;
              case MOVE_EFFECT_REMOVE_PARALYSIS:  
                  if (!(gBattleMons[gBattlerTarget].status1 & STATUS1_PARALYSIS))
                  {
                      gBattlescriptCurrInstr++;
                  }
                  else
                  {
                      gBattleMons[gBattlerTarget].status1 &= ~STATUS1_PARALYSIS;

                      gActiveBattler = gBattlerTarget;
                      BtlController_EmitSetMonData(B_COMM_TO_CONTROLLER, REQUEST_STATUS_BATTLE, 0, sizeof(gBattleMons[gActiveBattler].status1),gBattleMons[gActiveBattler].status1);
                      MarkBattlerForControllerExec(gActiveBattler);

                      BattleScriptPush(gBattlescriptCurrInstr + 1);
                      gBattlescriptCurrInstr = BattleScript_TargetPRLZHeal;
                  }
                  break;
              case MOVE_EFFECT_ATK_DEF_DOWN:  
                  BattleScriptPush(gBattlescriptCurrInstr + 1);
                  gBattlescriptCurrInstr = BattleScript_AtkDefDown;
                  break;
              case MOVE_EFFECT_RECOIL_33:  
                  gBattleMoveDamage = gHpDealt / 3;
                  if (gBattleMoveDamage == 0)
                      gBattleMoveDamage = 1;

                  BattleScriptPush(gBattlescriptCurrInstr + 1);
                  gBattlescriptCurrInstr = sMoveEffectBS_Ptrs[gBattleCommunication[MOVE_EFFECT_BYTE]];
                  break;
              case MOVE_EFFECT_THRASH:
                  if (gBattleMons[gEffectBattler].status2 & STATUS2_LOCK_CONFUSE)
                  {
                      gBattlescriptCurrInstr++;
                  }
                  else
                  {
                      gBattleMons[gEffectBattler].status2 |= STATUS2_MULTIPLETURNS;
                      gLockedMoves[gEffectBattler] = gCurrentMove;
                      gBattleMons[gEffectBattler].status2 |= STATUS2_LOCK_CONFUSE_TURN((Random() & 1) + 2);  
                  }
                  break;
              case MOVE_EFFECT_KNOCK_OFF:
                  if (gBattleMons[gEffectBattler].ability == ABILITY_STICKY_HOLD)
                  {
                      if (gBattleMons[gEffectBattler].item == ITEM_NONE)
                      {
                          gBattlescriptCurrInstr++;
                      }
                      else
                      {
                          gLastUsedAbility = ABILITY_STICKY_HOLD;
                          gBattlescriptCurrInstr = BattleScript_StickyHoldActivates;
                          RecordAbilityBattle(gEffectBattler, ABILITY_STICKY_HOLD);
                      }
                      break;
                  }
                  if (gBattleMons[gEffectBattler].item)
                  {
                      side = GetBattlerSide(gEffectBattler);

                      gLastUsedItem = gBattleMons[gEffectBattler].item;
                      gBattleMons[gEffectBattler].item = ITEM_NONE;
                      gWishFutureKnock.knockedOffMons[side] |= gBitTable[gBattlerPartyIndexes[gEffectBattler]];

                      BattleScriptPush(gBattlescriptCurrInstr + 1);
                      gBattlescriptCurrInstr = BattleScript_KnockedOff;

                      ((gBattleStruct.choicedMove[gEffectBattler]) + 0) = 0;
                      ((gBattleStruct.choicedMove[gEffectBattler]) + 1) = 0;
                  }
                  else
                  {
                      gBattlescriptCurrInstr++;
                  }
                  break;
              case MOVE_EFFECT_SP_ATK_TWO_DOWN:  
                  BattleScriptPush(gBattlescriptCurrInstr + 1);
                  gBattlescriptCurrInstr = BattleScript_SAtkDown2;
                  break;
              }
          }
      }

      gBattleCommunication[MOVE_EFFECT_BYTE] = 0;
}

/** static void Cmd_seteffectwithchance(void) */
export function Cmd_seteffectwithchance(): any {
  let percentChance: any = null;

      if (gBattleMons[gBattlerAttacker].ability == ABILITY_SERENE_GRACE)
          percentChance = gBattleMoves[gCurrentMove].secondaryEffectChance * 2;
      else
          percentChance = gBattleMoves[gCurrentMove].secondaryEffectChance;

      if (gBattleCommunication[MOVE_EFFECT_BYTE] & MOVE_EFFECT_CERTAIN
          && !(gMoveResultFlags & MOVE_RESULT_NO_EFFECT))
      {
          gBattleCommunication[MOVE_EFFECT_BYTE] &= ~MOVE_EFFECT_CERTAIN;
          SetMoveEffect(FALSE, MOVE_EFFECT_CERTAIN);
      }
      else if (Random() % 100 < percentChance
               && gBattleCommunication[MOVE_EFFECT_BYTE]
               && !(gMoveResultFlags & MOVE_RESULT_NO_EFFECT))
      {
          if (percentChance >= 100)
              SetMoveEffect(FALSE, MOVE_EFFECT_CERTAIN);
          else
              SetMoveEffect(FALSE, 0);
      }
      else
      {
          gBattlescriptCurrInstr++;
      }

      gBattleCommunication[MOVE_EFFECT_BYTE] = 0;
      gBattleScripting.multihitMoveEffect = 0;
}

/** static void Cmd_seteffectprimary(void) */
export function Cmd_seteffectprimary(): any {
  SetMoveEffect(TRUE, 0);
}

/** static void Cmd_seteffectsecondary(void) */
export function Cmd_seteffectsecondary(): any {
  SetMoveEffect(FALSE, 0);
}

/** static void Cmd_clearstatusfromeffect(void) */
export function Cmd_clearstatusfromeffect(): any {
  gActiveBattler = GetBattlerForBattleScript(gBattlescriptCurrInstr[1]);

      if (gBattleCommunication[MOVE_EFFECT_BYTE] <= PRIMARY_STATUS_MOVE_EFFECT)
          gBattleMons[gActiveBattler].status1 &= (~sStatusFlagsForMoveEffects[gBattleCommunication[MOVE_EFFECT_BYTE]]);
      else
          gBattleMons[gActiveBattler].status2 &= (~sStatusFlagsForMoveEffects[gBattleCommunication[MOVE_EFFECT_BYTE]]);

      gBattleCommunication[MOVE_EFFECT_BYTE] = 0;
      gBattlescriptCurrInstr += 2;
      gBattleScripting.multihitMoveEffect = 0;
}

/** static void Cmd_tryfaintmon(void) */
export function Cmd_tryfaintmon(): any {
  let BS_ptr: any = null;

      if (gBattlescriptCurrInstr[2] != 0)
      {
          gActiveBattler = GetBattlerForBattleScript(gBattlescriptCurrInstr[1]);
          if (gHitMarker & HITMARKER_FAINTED(gActiveBattler))
          {
              BS_ptr = T1_READ_PTR(gBattlescriptCurrInstr + 3);

              BattleScriptPop();
              gBattlescriptCurrInstr = BS_ptr;
              gSideStatuses[GetBattlerSide(gActiveBattler)] &= ~SIDE_STATUS_SPIKES_DAMAGED;
          }
          else
          {
              gBattlescriptCurrInstr += 7;
          }
      }
      else
      {
          let battler: any = null;

          if (gBattlescriptCurrInstr[1] == BS_ATTACKER)
          {
              gActiveBattler = gBattlerAttacker;
              battler = gBattlerTarget;
              BS_ptr = BattleScript_FaintAttacker;
          }
          else
          {
              gActiveBattler = gBattlerTarget;
              battler = gBattlerAttacker;
              BS_ptr = BattleScript_FaintTarget;
          }
          if (!(gAbsentBattlerFlags & gBitTable[gActiveBattler])
           && gBattleMons[gActiveBattler].hp == 0)
          {
              gHitMarker |= HITMARKER_FAINTED(gActiveBattler);
              BattleScriptPush(gBattlescriptCurrInstr + 7);
              gBattlescriptCurrInstr = BS_ptr;
              if (GetBattlerSide(gActiveBattler) == B_SIDE_PLAYER)
              {
                  gHitMarker |= HITMARKER_PLAYER_FAINTED;
                  if (gBattleResults.playerFaintCounter < 255)
                      gBattleResults.playerFaintCounter++;
                  AdjustFriendshipOnBattleFaint(gActiveBattler);
              }
              else
              {
                  if (gBattleResults.opponentFaintCounter < 255)
                      gBattleResults.opponentFaintCounter++;
                  gBattleResults.lastOpponentSpecies = GetMonData(gEnemyParty[gBattlerPartyIndexes[gActiveBattler]], MON_DATA_SPECIES, NULL);
              }
              if ((gHitMarker & HITMARKER_DESTINYBOND) && gBattleMons[gBattlerAttacker].hp != 0)
              {
                  gHitMarker &= ~HITMARKER_DESTINYBOND;
                  BattleScriptPush(gBattlescriptCurrInstr);
                  gBattleMoveDamage = gBattleMons[battler].hp;
                  gBattlescriptCurrInstr = BattleScript_DestinyBondTakesLife;
              }
              if ((gStatuses3[gBattlerTarget] & STATUS3_GRUDGE)
               && !(gHitMarker & HITMARKER_GRUDGE)
               && GetBattlerSide(gBattlerAttacker) != GetBattlerSide(gBattlerTarget)
               && gBattleMons[gBattlerAttacker].hp != 0
               && gCurrentMove != MOVE_STRUGGLE)
              {
                  let moveIndex: any = (gBattleStruct.chosenMovePositions + gBattlerAttacker);

                  gBattleMons[gBattlerAttacker].pp[moveIndex] = 0;
                  BattleScriptPush(gBattlescriptCurrInstr);
                  gBattlescriptCurrInstr = BattleScript_GrudgeTakesPp;
                  gActiveBattler = gBattlerAttacker;
                  BtlController_EmitSetMonData(B_COMM_TO_CONTROLLER, moveIndex + REQUEST_PPMOVE1_BATTLE, 0, sizeof(gBattleMons[gActiveBattler].pp[moveIndex]),gBattleMons[gActiveBattler].pp[moveIndex]);
                  MarkBattlerForControllerExec(gActiveBattler);

                  PREPARE_MOVE_BUFFER(gBattleTextBuff1, gBattleMons[gBattlerAttacker].moves[moveIndex])
              }
          }
          else
          {
              gBattlescriptCurrInstr += 7;
          }
      }
}

/** static void Cmd_dofaintanimation(void) */
export function Cmd_dofaintanimation(): any {
  if (gBattleControllerExecFlags == 0)
      {
          gActiveBattler = GetBattlerForBattleScript(gBattlescriptCurrInstr[1]);
          BtlController_EmitFaintAnimation(B_COMM_TO_CONTROLLER);
          MarkBattlerForControllerExec(gActiveBattler);
          gBattlescriptCurrInstr += 2;
      }
}

/** static void Cmd_cleareffectsonfaint(void) */
export function Cmd_cleareffectsonfaint(): any {
  if (gBattleControllerExecFlags == 0)
      {
          gActiveBattler = GetBattlerForBattleScript(gBattlescriptCurrInstr[1]);

          if (!(gBattleTypeFlags & BATTLE_TYPE_ARENA) || gBattleMons[gActiveBattler].hp == 0)
          {
              gBattleMons[gActiveBattler].status1 = 0;
              BtlController_EmitSetMonData(B_COMM_TO_CONTROLLER, REQUEST_STATUS_BATTLE, 0, sizeof(gBattleMons[gActiveBattler].status1),gBattleMons[gActiveBattler].status1);
              MarkBattlerForControllerExec(gActiveBattler);
          }

          FaintClearSetData();  
          gBattlescriptCurrInstr += 2;
      }
}

/** static void Cmd_jumpifstatus(void) */
export function Cmd_jumpifstatus(): any {
  let battler: any = GetBattlerForBattleScript(gBattlescriptCurrInstr[1]);
      let flags: any = T2_READ_32(gBattlescriptCurrInstr + 2);
      let jumpPtr: any = T2_READ_PTR(gBattlescriptCurrInstr + 6);

      if (gBattleMons[battler].status1 & flags && gBattleMons[battler].hp != 0)
          gBattlescriptCurrInstr = jumpPtr;
      else
          gBattlescriptCurrInstr += 10;
}

/** static void Cmd_jumpifstatus2(void) */
export function Cmd_jumpifstatus2(): any {
  let battler: any = GetBattlerForBattleScript(gBattlescriptCurrInstr[1]);
      let flags: any = T2_READ_32(gBattlescriptCurrInstr + 2);
      let jumpPtr: any = T2_READ_PTR(gBattlescriptCurrInstr + 6);

      if (gBattleMons[battler].status2 & flags && gBattleMons[battler].hp != 0)
          gBattlescriptCurrInstr = jumpPtr;
      else
          gBattlescriptCurrInstr += 10;
}

/** static void Cmd_jumpifability(void) */
export function Cmd_jumpifability(): any {
  let battler: any = null;
      let ability: any = gBattlescriptCurrInstr[2];
      let jumpPtr: any = T2_READ_PTR(gBattlescriptCurrInstr + 3);

      if (gBattlescriptCurrInstr[1] == BS_ATTACKER_SIDE)
      {
          battler = AbilityBattleEffects(ABILITYEFFECT_CHECK_BATTLER_SIDE, gBattlerAttacker, ability, 0, 0);
          if (battler)
          {
              gLastUsedAbility = ability;
              gBattlescriptCurrInstr = jumpPtr;
              RecordAbilityBattle(battler - 1, gLastUsedAbility);
              gBattleScripting.battlerWithAbility = battler - 1;
          }
          else
          {
              gBattlescriptCurrInstr += 7;
          }
      }
      else if (gBattlescriptCurrInstr[1] == BS_NOT_ATTACKER_SIDE)
      {
          battler = AbilityBattleEffects(ABILITYEFFECT_CHECK_OTHER_SIDE, gBattlerAttacker, ability, 0, 0);
          if (battler)
          {
              gLastUsedAbility = ability;
              gBattlescriptCurrInstr = jumpPtr;
              RecordAbilityBattle(battler - 1, gLastUsedAbility);
              gBattleScripting.battlerWithAbility = battler - 1;
          }
          else
          {
              gBattlescriptCurrInstr += 7;
          }
      }
      else
      {
          battler = GetBattlerForBattleScript(gBattlescriptCurrInstr[1]);
          if (gBattleMons[battler].ability == ability)
          {
              gLastUsedAbility = ability;
              gBattlescriptCurrInstr = jumpPtr;
              RecordAbilityBattle(battler, gLastUsedAbility);
              gBattleScripting.battlerWithAbility = battler;
          }
          else
          {
              gBattlescriptCurrInstr += 7;
          }
      }
}

/** static void Cmd_jumpifsideaffecting(void) */
export function Cmd_jumpifsideaffecting(): any {
  let side: any = null;
      let flags: any = null;
      let jumpPtr: any = null;

      if (gBattlescriptCurrInstr[1] == BS_ATTACKER)
          side = GET_BATTLER_SIDE(gBattlerAttacker);
      else
          side = GET_BATTLER_SIDE(gBattlerTarget);

      flags = T2_READ_16(gBattlescriptCurrInstr + 2);
      jumpPtr = T2_READ_PTR(gBattlescriptCurrInstr + 4);

      if (gSideStatuses[side] & flags)
          gBattlescriptCurrInstr = jumpPtr;
      else
          gBattlescriptCurrInstr += 8;
}

/** static void Cmd_jumpifstat(void) */
export function Cmd_jumpifstat(): any {
  let ret: any = 0;
      let battler: any = GetBattlerForBattleScript(gBattlescriptCurrInstr[1]);
      let value: any = gBattleMons[battler].statStages[gBattlescriptCurrInstr[3]];

      switch (gBattlescriptCurrInstr[2])
      {
      case CMP_EQUAL:
          if (value == gBattlescriptCurrInstr[4])
              ret++;
          break;
      case CMP_NOT_EQUAL:
          if (value != gBattlescriptCurrInstr[4])
              ret++;
          break;
      case CMP_GREATER_THAN:
          if (value > gBattlescriptCurrInstr[4])
              ret++;
          break;
      case CMP_LESS_THAN:
          if (value < gBattlescriptCurrInstr[4])
              ret++;
          break;
      case CMP_COMMON_BITS:
          if (value & gBattlescriptCurrInstr[4])
              ret++;
          break;
      case CMP_NO_COMMON_BITS:
          if (!(value & gBattlescriptCurrInstr[4]))
              ret++;
          break;
      }

      if (ret)
          gBattlescriptCurrInstr = T2_READ_PTR(gBattlescriptCurrInstr + 5);
      else
          gBattlescriptCurrInstr += 9;
}

/** static void Cmd_jumpifstatus3condition(void) */
export function Cmd_jumpifstatus3condition(): any {
  let status: any = null;
      let jumpPtr: any = null;

      gActiveBattler = GetBattlerForBattleScript(gBattlescriptCurrInstr[1]);
      status = T2_READ_32(gBattlescriptCurrInstr + 2);
      jumpPtr = T2_READ_PTR(gBattlescriptCurrInstr + 7);

      if (gBattlescriptCurrInstr[6])
      {
          if ((gStatuses3[gActiveBattler] & status) != 0)
              gBattlescriptCurrInstr += 11;
          else
              gBattlescriptCurrInstr = jumpPtr;
      }
      else
      {
          if ((gStatuses3[gActiveBattler] & status) != 0)
              gBattlescriptCurrInstr = jumpPtr;
          else
              gBattlescriptCurrInstr += 11;
      }
}

