/** static void Cmd_jumpifarrayequal(void) */
export function Cmd_jumpifarrayequal(): any {
  let mem1: any = T2_READ_PTR(gBattlescriptCurrInstr + 1);
      let mem2: any = T2_READ_PTR(gBattlescriptCurrInstr + 5);
      let size: any = gBattlescriptCurrInstr[9];
      let jumpPtr: any = T2_READ_PTR(gBattlescriptCurrInstr + 10);

      let i: any = null;
      for (i = 0; i < size; i++)
      {
          if (mem1 != mem2)
          {
              gBattlescriptCurrInstr += 14;
              break;
          }
          mem1++, mem2++;
      }

      if (i == size)
          gBattlescriptCurrInstr = jumpPtr;
}

/** static void Cmd_jumpifarraynotequal(void) */
export function Cmd_jumpifarraynotequal(): any {
  let equalBytes: any = 0;
      let mem1: any = T2_READ_PTR(gBattlescriptCurrInstr + 1);
      let mem2: any = T2_READ_PTR(gBattlescriptCurrInstr + 5);
      let size: any = gBattlescriptCurrInstr[9];
      let jumpPtr: any = T2_READ_PTR(gBattlescriptCurrInstr + 10);

      let i: any = null;
      for (i = 0; i < size; i++)
      {
          if (mem1 == mem2)
              equalBytes++;
          mem1++, mem2++;
      }

      if (equalBytes != size)
          gBattlescriptCurrInstr = jumpPtr;
      else
          gBattlescriptCurrInstr += 14;
}

/** static void Cmd_setbyte(void) */
export function Cmd_setbyte(): any {
  let memByte: any = T2_READ_PTR(gBattlescriptCurrInstr + 1);
      memByte = gBattlescriptCurrInstr[5];

      gBattlescriptCurrInstr += 6;
}

