/** static void Cmd_handlelearnnewmove(void) */
export function Cmd_handlelearnnewmove(): any {
  let learnedMovePtr: any = T1_READ_PTR(gBattlescriptCurrInstr + 1);
      let nothingToLearnPtr: any = T1_READ_PTR(gBattlescriptCurrInstr + 5);

      let learnMove: any = MonTryLearningNewMove(gPlayerParty[gBattleStruct.expGetterMonId], gBattlescriptCurrInstr[9]);
      while (learnMove == MON_ALREADY_KNOWS_MOVE)
          learnMove = MonTryLearningNewMove(gPlayerParty[gBattleStruct.expGetterMonId], FALSE);

      if (learnMove == MOVE_NONE)
      {
          gBattlescriptCurrInstr = nothingToLearnPtr;
      }
      else if (learnMove == MON_HAS_MAX_MOVES)
      {
          gBattlescriptCurrInstr += 10;
      }
      else
      {
          gActiveBattler = GetBattlerAtPosition(B_POSITION_PLAYER_LEFT);

          if (gBattlerPartyIndexes[gActiveBattler] == gBattleStruct.expGetterMonId
              && !(gBattleMons[gActiveBattler].status2 & STATUS2_TRANSFORMED))
          {
              GiveMoveToBattleMon(gBattleMons[gActiveBattler], learnMove);
          }
          if (gBattleTypeFlags & BATTLE_TYPE_DOUBLE)
          {
              gActiveBattler = GetBattlerAtPosition(B_POSITION_PLAYER_RIGHT);
              if (gBattlerPartyIndexes[gActiveBattler] == gBattleStruct.expGetterMonId
                  && !(gBattleMons[gActiveBattler].status2 & STATUS2_TRANSFORMED))
              {
                  GiveMoveToBattleMon(gBattleMons[gActiveBattler], learnMove);
              }
          }

          gBattlescriptCurrInstr = learnedMovePtr;
      }
}

/** static void Cmd_yesnoboxlearnmove(void) */
export function Cmd_yesnoboxlearnmove(): any {
  gActiveBattler = 0;

      switch (gBattleScripting.learnMoveState)
      {
      case 0:
          HandleBattleWindow(YESNOBOX_X_Y, 0);
          BattlePutTextOnWindow(gText_BattleYesNoChoice, B_WIN_YESNO);
          gBattleScripting.learnMoveState++;
          gBattleCommunication[CURSOR_POSITION] = 0;
          BattleCreateYesNoCursorAt(0);
          break;
      case 1:
          if (JOY_NEW(DPAD_UP) && gBattleCommunication[CURSOR_POSITION] != 0)
          {
              PlaySE(SE_SELECT);
              BattleDestroyYesNoCursorAt(gBattleCommunication[CURSOR_POSITION]);
              gBattleCommunication[CURSOR_POSITION] = 0;
              BattleCreateYesNoCursorAt(0);
          }
          if (JOY_NEW(DPAD_DOWN) && gBattleCommunication[CURSOR_POSITION] == 0)
          {
              PlaySE(SE_SELECT);
              BattleDestroyYesNoCursorAt(gBattleCommunication[CURSOR_POSITION]);
              gBattleCommunication[CURSOR_POSITION] = 1;
              BattleCreateYesNoCursorAt(1);
          }
          if (JOY_NEW(A_BUTTON))
          {
              PlaySE(SE_SELECT);
              if (gBattleCommunication[1] == 0)
              {
                  HandleBattleWindow(YESNOBOX_X_Y, WINDOW_CLEAR);
                  BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
                  gBattleScripting.learnMoveState++;
              }
              else
              {
                  gBattleScripting.learnMoveState = 5;
              }
          }
          else if (JOY_NEW(B_BUTTON))
          {
              PlaySE(SE_SELECT);
              gBattleScripting.learnMoveState = 5;
          }
          break;
      case 2:
          if (!gPaletteFade.active)
          {
              FreeAllWindowBuffers();
              ShowSelectMovePokemonSummaryScreen(gPlayerParty, gBattleStruct.expGetterMonId, gPlayerPartyCount - 1, ReshowBattleScreenAfterMenu, gMoveToLearn);
              gBattleScripting.learnMoveState++;
          }
          break;
      case 3:
          if (!gPaletteFade.active && gMain.callback2 == BattleMainCB2)
          {
              gBattleScripting.learnMoveState++;
          }
          break;
      case 4:
          if (!gPaletteFade.active && gMain.callback2 == BattleMainCB2)
          {
              let movePosition: any = GetMoveSlotToReplace();
              if (movePosition == MAX_MON_MOVES)
              {
                  gBattleScripting.learnMoveState = 5;
              }
              else
              {
                  let move: any = GetMonData(gPlayerParty[gBattleStruct.expGetterMonId], MON_DATA_MOVE1 + movePosition);
                  if (IsHMMove2(move))
                  {
                      PrepareStringBattle(STRINGID_HMMOVESCANTBEFORGOTTEN, gActiveBattler);
                      gBattleScripting.learnMoveState = 6;
                  }
                  else
                  {
                      gBattlescriptCurrInstr = T1_READ_PTR(gBattlescriptCurrInstr + 1);

                      PREPARE_MOVE_BUFFER(gBattleTextBuff2, move)

                      RemoveMonPPBonus(gPlayerParty[gBattleStruct.expGetterMonId], movePosition);
                      SetMonMoveSlot(gPlayerParty[gBattleStruct.expGetterMonId], gMoveToLearn, movePosition);

                      if (gBattlerPartyIndexes[0] == gBattleStruct.expGetterMonId && MOVE_IS_PERMANENT(0, movePosition))
                      {
                          RemoveBattleMonPPBonus(gBattleMons[0], movePosition);
                          SetBattleMonMoveSlot(gBattleMons[0], gMoveToLearn, movePosition);
                      }
                      if (gBattleTypeFlags & BATTLE_TYPE_DOUBLE
                          && gBattlerPartyIndexes[2] == gBattleStruct.expGetterMonId
                          && MOVE_IS_PERMANENT(2, movePosition))
                      {
                          RemoveBattleMonPPBonus(gBattleMons[2], movePosition);
                          SetBattleMonMoveSlot(gBattleMons[2], gMoveToLearn, movePosition);
                      }
                  }
              }
          }
          break;
      case 5:
          HandleBattleWindow(YESNOBOX_X_Y, WINDOW_CLEAR);
          gBattlescriptCurrInstr += 5;
          break;
      case 6:
          if (gBattleControllerExecFlags == 0)
          {
              gBattleScripting.learnMoveState = 2;
          }
          break;
      }
}

