/** static void Cmd_hpthresholds(void) */
export function Cmd_hpthresholds(): any {
  let opposingBattler: any = null;
      let result: any = null;

      if (!(gBattleTypeFlags & BATTLE_TYPE_DOUBLE))
      {
          gActiveBattler = GetBattlerForBattleScript(gBattlescriptCurrInstr[1]);
          opposingBattler = BATTLE_OPPOSITE(gActiveBattler);

          result = gBattleMons[opposingBattler].hp * 100 / gBattleMons[opposingBattler].maxHP;
          if (result == 0)
              result = 1;

          if (result > 69 || gBattleMons[opposingBattler].hp == 0)
              gBattleStruct.hpScale = 0;
          else if (result > 39)
              gBattleStruct.hpScale = 1;
          else if (result > 9)
              gBattleStruct.hpScale = 2;
          else
              gBattleStruct.hpScale = 3;
      }

      gBattlescriptCurrInstr += 2;
}

/** static void Cmd_hpthresholds2(void) */
export function Cmd_hpthresholds2(): any {
  let opposingBattler: any = null;
      let result: any = null;
      let hpSwitchout: any = null;

      if (!(gBattleTypeFlags & BATTLE_TYPE_DOUBLE))
      {
          gActiveBattler = GetBattlerForBattleScript(gBattlescriptCurrInstr[1]);
          opposingBattler = BATTLE_OPPOSITE(gActiveBattler);
          hpSwitchout = (gBattleStruct.hpOnSwitchout + GetBattlerSide(opposingBattler));
          result = (hpSwitchout - gBattleMons[opposingBattler].hp) * 100 / hpSwitchout;

          if (gBattleMons[opposingBattler].hp >= hpSwitchout)
              gBattleStruct.hpScale = 0;
          else if (result <= 29)
              gBattleStruct.hpScale = 1;
          else if (result <= 69)
              gBattleStruct.hpScale = 2;
          else
              gBattleStruct.hpScale = 3;
      }

      gBattlescriptCurrInstr += 2;
}

