export function Cmd_various(): any {
  let side: any = null;
      let i: any = null;

      gActiveBattler = GetBattlerForBattleScript(gBattlescriptCurrInstr[1]);

      switch (gBattlescriptCurrInstr[2])
      {
      case VARIOUS_CANCEL_MULTI_TURN_MOVES:
          CancelMultiTurnMoves(gActiveBattler);
          break;
      case VARIOUS_SET_MAGIC_COAT_TARGET:
          gBattlerAttacker = gBattlerTarget;
          side = BATTLE_OPPOSITE(GetBattlerSide(gBattlerAttacker));
          if (gSideTimers[side].followmeTimer != 0 && gBattleMons[gSideTimers[side].followmeTarget].hp != 0)
              gBattlerTarget = gSideTimers[side].followmeTarget;
          else
              gBattlerTarget = gActiveBattler;
          break;
      case VARIOUS_IS_RUNNING_IMPOSSIBLE:
          gBattleCommunication[0] = IsRunningFromBattleImpossible();
          break;
      case VARIOUS_GET_MOVE_TARGET:
          gBattlerTarget = GetMoveTarget(gCurrentMove, NO_TARGET_OVERRIDE);
          break;
      case VARIOUS_GET_BATTLER_FAINTED:
          if (gHitMarker & HITMARKER_FAINTED(gActiveBattler))
              gBattleCommunication[0] = TRUE;
          else
              gBattleCommunication[0] = FALSE;
          break;
      case VARIOUS_RESET_INTIMIDATE_TRACE_BITS:
          gSpecialStatuses[gActiveBattler].intimidatedMon = 0;
          gSpecialStatuses[gActiveBattler].traced = 0;
          break;
      case VARIOUS_UPDATE_CHOICE_MOVE_ON_LVL_UP:
          if (gBattlerPartyIndexes[0] == gBattleStruct.expGetterMonId || gBattlerPartyIndexes[2] == gBattleStruct.expGetterMonId)
          {
              let choicedMove: any = null;

              if (gBattlerPartyIndexes[0] == gBattleStruct.expGetterMonId)
                  gActiveBattler = 0;
              else
                  gActiveBattler = 2;

              choicedMove =gBattleStruct.choicedMove[gActiveBattler];

              for (i = 0; i < MAX_MON_MOVES; i++)
              {
                  if (gBattleMons[gActiveBattler].moves[i] == choicedMove)
                      break;
              }
              if (i == MAX_MON_MOVES)
                  choicedMove = MOVE_NONE;
          }
          break;
      case VARIOUS_RESET_PLAYER_FAINTED:
          if (!(gBattleTypeFlags & (BATTLE_TYPE_LINK | BATTLE_TYPE_DOUBLE))
              && gBattleTypeFlags & BATTLE_TYPE_TRAINER
              && gBattleMons[0].hp != 0
              && gBattleMons[1].hp != 0)
          {
              gHitMarker &= ~HITMARKER_PLAYER_FAINTED;
          }
          break;
      case VARIOUS_PALACE_FLAVOR_TEXT:
           
          gBattleCommunication[0] = FALSE;  
          gBattleScripting.battler = gActiveBattler = gBattleCommunication[1];

          if (!(gBattleStruct.palaceFlags & gBitTable[gActiveBattler])
              && gBattleMons[gActiveBattler].maxHP / 2 >= gBattleMons[gActiveBattler].hp
              && gBattleMons[gActiveBattler].hp != 0
              && !(gBattleMons[gActiveBattler].status1 & STATUS1_SLEEP))
          {
              gBattleStruct.palaceFlags |= gBitTable[gActiveBattler];
              gBattleCommunication[0] = TRUE;
              gBattleCommunication[MULTISTRING_CHOOSER] = sBattlePalaceNatureToFlavorTextId[GetNatureFromPersonality(gBattleMons[gActiveBattler].personality)];
          }
          break;
      case VARIOUS_ARENA_JUDGMENT_WINDOW:
          i = BattleArena_ShowJudgmentWindow(gBattleCommunication[0]);

           
           
          if (i == ARENA_RESULT_RUNNING)
              return;

          gBattleCommunication[1] = i;
          break;
      case VARIOUS_ARENA_OPPONENT_MON_LOST:
          gBattleMons[1].hp = 0;
          gHitMarker |= HITMARKER_FAINTED(1);
          gBattleStruct.arenaLostOpponentMons |= gBitTable[gBattlerPartyIndexes[1]];
          gDisableStructs[1].truantSwitchInHack = 1;
          break;
      case VARIOUS_ARENA_PLAYER_MON_LOST:
          gBattleMons[0].hp = 0;
          gHitMarker |= HITMARKER_FAINTED(0);
          gHitMarker |= HITMARKER_PLAYER_FAINTED;
          gBattleStruct.arenaLostPlayerMons |= gBitTable[gBattlerPartyIndexes[0]];
          gDisableStructs[0].truantSwitchInHack = 1;
          break;
      case VARIOUS_ARENA_BOTH_MONS_LOST:
          gBattleMons[0].hp = 0;
          gBattleMons[1].hp = 0;
          gHitMarker |= HITMARKER_FAINTED(0);
          gHitMarker |= HITMARKER_FAINTED(1);
          gHitMarker |= HITMARKER_PLAYER_FAINTED;
          gBattleStruct.arenaLostPlayerMons |= gBitTable[gBattlerPartyIndexes[0]];
          gBattleStruct.arenaLostOpponentMons |= gBitTable[gBattlerPartyIndexes[1]];
          gDisableStructs[0].truantSwitchInHack = 1;
          gDisableStructs[1].truantSwitchInHack = 1;
          break;
      case VARIOUS_EMIT_YESNOBOX:
          BtlController_EmitYesNoBox(B_COMM_TO_CONTROLLER);
          MarkBattlerForControllerExec(gActiveBattler);
          break;
      case VARIOUS_DRAW_ARENA_REF_TEXT_BOX:
          DrawArenaRefereeTextBox();
          break;
      case VARIOUS_ERASE_ARENA_REF_TEXT_BOX:
          EraseArenaRefereeTextBox();
          break;
      case VARIOUS_ARENA_JUDGMENT_STRING:
          BattleStringExpandPlaceholdersToDisplayedString(gRefereeStringsTable[gBattlescriptCurrInstr[1]]);
          BattlePutTextOnWindow(gDisplayedStringBattle, ARENA_WIN_JUDGMENT_TEXT);
          break;
      case VARIOUS_ARENA_WAIT_STRING:
          if (IsTextPrinterActive(ARENA_WIN_JUDGMENT_TEXT))
              return;
          break;
      case VARIOUS_WAIT_CRY:
          if (!IsCryFinished())
              return;
          break;
      case VARIOUS_RETURN_OPPONENT_MON1:
          gActiveBattler = 1;
          if (gBattleMons[gActiveBattler].hp != 0)
          {
              BtlController_EmitReturnMonToBall(B_COMM_TO_CONTROLLER, FALSE);
              MarkBattlerForControllerExec(gActiveBattler);
          }
          break;
      case VARIOUS_RETURN_OPPONENT_MON2:
          if (gBattlersCount > 3)
          {
              gActiveBattler = 3;
              if (gBattleMons[gActiveBattler].hp != 0)
              {
                  BtlController_EmitReturnMonToBall(B_COMM_TO_CONTROLLER, FALSE);
                  MarkBattlerForControllerExec(gActiveBattler);
              }
          }
          break;
      case VARIOUS_VOLUME_DOWN:
          m4aMPlayVolumeControl(gMPlayInfo_BGM, TRACKS_ALL, _0x55);
          break;
      case VARIOUS_VOLUME_UP:
          m4aMPlayVolumeControl(gMPlayInfo_BGM, TRACKS_ALL, _0x100);
          break;
      case VARIOUS_SET_ALREADY_STATUS_MOVE_ATTEMPT:
          gBattleStruct.alreadyStatusedMoveAttempt |= gBitTable[gActiveBattler];
          break;
      case VARIOUS_PALACE_TRY_ESCAPE_STATUS:
          if (BattlePalace_TryEscapeStatus(gActiveBattler))
              return;
          break;
      case VARIOUS_SET_TELEPORT_OUTCOME:
          if (GetBattlerSide(gActiveBattler) == B_SIDE_PLAYER)
              gBattleOutcome = B_OUTCOME_PLAYER_TELEPORTED;
          else
              gBattleOutcome = B_OUTCOME_MON_TELEPORTED;
          break;
      case VARIOUS_PLAY_TRAINER_DEFEATED_MUSIC:
          BtlController_EmitPlayFanfareOrBGM(B_COMM_TO_CONTROLLER, MUS_VICTORY_TRAINER, TRUE);
          MarkBattlerForControllerExec(gActiveBattler);
          break;
      }

      gBattlescriptCurrInstr += 3;
}

/** static void Cmd_setprotectlike(void) */
export function Cmd_setprotectlike(): any {
  let notLastTurn: any = TRUE;
      let lastMove: any = gLastResultingMoves[gBattlerAttacker];

      if (lastMove != MOVE_PROTECT && lastMove != MOVE_DETECT && lastMove != MOVE_ENDURE)
          gDisableStructs[gBattlerAttacker].protectUses = 0;

      if (gCurrentTurnActionNumber == (gBattlersCount - 1))
          notLastTurn = FALSE;

      if (sProtectSuccessRates[gDisableStructs[gBattlerAttacker].protectUses] >= Random() && notLastTurn)
      {
          if (gBattleMoves[gCurrentMove].effect == EFFECT_PROTECT)
          {
              gProtectStructs[gBattlerAttacker].protected = 1;
              gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_PROTECTED_ITSELF;
          }
          if (gBattleMoves[gCurrentMove].effect == EFFECT_ENDURE)
          {
              gProtectStructs[gBattlerAttacker].endured = 1;
              gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_BRACED_ITSELF;
          }
          gDisableStructs[gBattlerAttacker].protectUses++;
      }
      else
      {
          gDisableStructs[gBattlerAttacker].protectUses = 0;
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_PROTECT_FAILED;
          gMoveResultFlags |= MOVE_RESULT_MISSED;
      }

      gBattlescriptCurrInstr++;
}

/** static void Cmd_tryexplosion(void) */
export function Cmd_tryexplosion(): any {
  if (gBattleControllerExecFlags)
          return;

       
      for (gBattlerTarget = 0; gBattlerTarget < gBattlersCount; gBattlerTarget++)
      {
          if (gBattleMons[gBattlerTarget].ability == ABILITY_DAMP)
              break;
      }

      if (gBattlerTarget == gBattlersCount)
      {
           
          gActiveBattler = gBattlerAttacker;
          gBattleMoveDamage = gBattleMons[gActiveBattler].hp;
          BtlController_EmitHealthBarUpdate(B_COMM_TO_CONTROLLER, INSTANT_HP_BAR_DROP);
          MarkBattlerForControllerExec(gActiveBattler);
          gBattlescriptCurrInstr++;

           
          for (gBattlerTarget = 0; gBattlerTarget < gBattlersCount; gBattlerTarget++)
          {
              if (gBattlerTarget == gBattlerAttacker)
                  continue;
              if (!(gAbsentBattlerFlags & gBitTable[gBattlerTarget]))
                  break;
          }
      }
      else
      {
           
          gLastUsedAbility = ABILITY_DAMP;
          RecordAbilityBattle(gBattlerTarget, gBattleMons[gBattlerTarget].ability);
          gBattlescriptCurrInstr = BattleScript_DampStopsExplosion;
      }
}

/** static void Cmd_setatkhptozero(void) */
export function Cmd_setatkhptozero(): any {
  if (gBattleControllerExecFlags)
          return;

      gActiveBattler = gBattlerAttacker;
      gBattleMons[gActiveBattler].hp = 0;
      BtlController_EmitSetMonData(B_COMM_TO_CONTROLLER, REQUEST_HP_BATTLE, 0, sizeof(gBattleMons[gActiveBattler].hp),gBattleMons[gActiveBattler].hp);
      MarkBattlerForControllerExec(gActiveBattler);

      gBattlescriptCurrInstr++;
}

/** static void Cmd_jumpifnexttargetvalid(void) */
export function Cmd_jumpifnexttargetvalid(): any {
  let jumpPtr: any = T1_READ_PTR(gBattlescriptCurrInstr + 1);

      if (gBattleTypeFlags & BATTLE_TYPE_DOUBLE)
      {
          for (gBattlerTarget++; ; gBattlerTarget++)
          {
              if (gBattlerTarget == gBattlerAttacker)
                  continue;
              if (!(gAbsentBattlerFlags & gBitTable[gBattlerTarget]))
                  break;
          }

          if (gBattlerTarget >= gBattlersCount)
              gBattlescriptCurrInstr += 5;
          else
              gBattlescriptCurrInstr = jumpPtr;
      }
      else
      {
          gBattlescriptCurrInstr += 5;
      }
}

/** static void Cmd_tryhealhalfhealth(void) */
export function Cmd_tryhealhalfhealth(): any {
  let failPtr: any = T1_READ_PTR(gBattlescriptCurrInstr + 1);

      if (gBattlescriptCurrInstr[5] == BS_ATTACKER)
          gBattlerTarget = gBattlerAttacker;

      gBattleMoveDamage = gBattleMons[gBattlerTarget].maxHP / 2;
      if (gBattleMoveDamage == 0)
          gBattleMoveDamage = 1;
      gBattleMoveDamage *= -1;

      if (gBattleMons[gBattlerTarget].hp == gBattleMons[gBattlerTarget].maxHP)
          gBattlescriptCurrInstr = failPtr;
      else
          gBattlescriptCurrInstr += 6;
}

/** static void Cmd_trymirrormove(void) */
export function Cmd_trymirrormove(): any {
  let validMovesCount: any = null;
      let i: any = null;
      let move: any = null;
      const validMoves: any[] = [];

      for (i = 0; i < (MAX_BATTLERS_COUNT - 1); i++)  
          validMoves[i] = MOVE_NONE;

      for (validMovesCount = 0, i = 0; i < gBattlersCount; i++)
      {
          if (i != gBattlerAttacker)
          {
              move = T1_READ_16(i * 2 + gBattlerAttacker * 8 + gBattleStruct.lastTakenMoveFrom);

              if (move != MOVE_NONE && move != MOVE_UNAVAILABLE)
              {
                  validMoves[validMovesCount] = move;
                  validMovesCount++;
              }
          }
      }

      move = T1_READ_16(gBattleStruct.lastTakenMove + gBattlerAttacker * 2);

      if (move != MOVE_NONE && move != MOVE_UNAVAILABLE)
      {
          gHitMarker &= ~HITMARKER_ATTACKSTRING_PRINTED;
          gCurrentMove = move;
          gBattlerTarget = GetMoveTarget(gCurrentMove, NO_TARGET_OVERRIDE);
          gBattlescriptCurrInstr = gBattleScriptsForMoveEffects[gBattleMoves[gCurrentMove].effect];
      }
      else if (validMovesCount != 0)
      {
          gHitMarker &= ~HITMARKER_ATTACKSTRING_PRINTED;
          i = Random() % validMovesCount;
          gCurrentMove = validMoves[i];
          gBattlerTarget = GetMoveTarget(gCurrentMove, NO_TARGET_OVERRIDE);
          gBattlescriptCurrInstr = gBattleScriptsForMoveEffects[gBattleMoves[gCurrentMove].effect];
      }
      else  
      {
          gSpecialStatuses[gBattlerAttacker].ppNotAffectedByPressure = TRUE;
          gBattlescriptCurrInstr++;
      }
}

/** static void Cmd_setrain(void) */
export function Cmd_setrain(): any {
  if (gBattleWeather & B_WEATHER_RAIN)
      {
          gMoveResultFlags |= MOVE_RESULT_MISSED;
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_WEATHER_FAILED;
      }
      else
      {
          gBattleWeather = B_WEATHER_RAIN_TEMPORARY;
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_STARTED_RAIN;
          gWishFutureKnock.weatherDuration = 5;
      }
      gBattlescriptCurrInstr++;
}

/** static void Cmd_setreflect(void) */
export function Cmd_setreflect(): any {
  if (gSideStatuses[GET_BATTLER_SIDE(gBattlerAttacker)] & SIDE_STATUS_REFLECT)
      {
          gMoveResultFlags |= MOVE_RESULT_MISSED;
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_SIDE_STATUS_FAILED;
      }
      else
      {
          gSideStatuses[GET_BATTLER_SIDE(gBattlerAttacker)] |= SIDE_STATUS_REFLECT;
          gSideTimers[GET_BATTLER_SIDE(gBattlerAttacker)].reflectTimer = 5;
          gSideTimers[GET_BATTLER_SIDE(gBattlerAttacker)].reflectBattlerId = gBattlerAttacker;

          if (gBattleTypeFlags & BATTLE_TYPE_DOUBLE && CountAliveMonsInBattle(BATTLE_ALIVE_ATK_SIDE) == 2)
              gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_SET_REFLECT_DOUBLE;
          else
              gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_SET_REFLECT_SINGLE;
      }
      gBattlescriptCurrInstr++;
}

/** static void Cmd_setseeded(void) */
export function Cmd_setseeded(): any {
  if (gMoveResultFlags & MOVE_RESULT_NO_EFFECT || gStatuses3[gBattlerTarget] & STATUS3_LEECHSEED)
      {
          gMoveResultFlags |= MOVE_RESULT_MISSED;
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_LEECH_SEED_MISS;
      }
      else if (IS_BATTLER_OF_TYPE(gBattlerTarget, TYPE_GRASS))
      {
          gMoveResultFlags |= MOVE_RESULT_MISSED;
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_LEECH_SEED_FAIL;
      }
      else
      {
          gStatuses3[gBattlerTarget] |= gBattlerAttacker;
          gStatuses3[gBattlerTarget] |= STATUS3_LEECHSEED;
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_LEECH_SEED_SET;
      }

      gBattlescriptCurrInstr++;
}

/** static void Cmd_manipulatedamage(void) */
export function Cmd_manipulatedamage(): any {
  switch (gBattlescriptCurrInstr[1])
      {
      case DMG_CHANGE_SIGN:
          gBattleMoveDamage *= -1;
          break;
      case DMG_RECOIL_FROM_MISS:
          gBattleMoveDamage /= 2;
          if (gBattleMoveDamage == 0)
              gBattleMoveDamage = 1;
          if ((gBattleMons[gBattlerTarget].maxHP / 2) < gBattleMoveDamage)
              gBattleMoveDamage = gBattleMons[gBattlerTarget].maxHP / 2;
          break;
      case DMG_DOUBLED:
          gBattleMoveDamage *= 2;
          break;
      }

      gBattlescriptCurrInstr += 2;
}

/** static void Cmd_trysetrest(void) */
export function Cmd_trysetrest(): any {
  let failJump: any = T1_READ_PTR(gBattlescriptCurrInstr + 1);
      gActiveBattler = gBattlerTarget = gBattlerAttacker;
      gBattleMoveDamage = gBattleMons[gBattlerTarget].maxHP * (-1);

      if (gBattleMons[gBattlerTarget].hp == gBattleMons[gBattlerTarget].maxHP)
      {
          gBattlescriptCurrInstr = failJump;
      }
      else
      {
          if (gBattleMons[gBattlerTarget].status1 & ((~STATUS1_SLEEP)))
              gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_REST_STATUSED;
          else
              gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_REST;

          gBattleMons[gBattlerTarget].status1 = STATUS1_SLEEP_TURN(3);
          BtlController_EmitSetMonData(B_COMM_TO_CONTROLLER, REQUEST_STATUS_BATTLE, 0, sizeof(gBattleMons[gActiveBattler].status1),gBattleMons[gActiveBattler].status1);
          MarkBattlerForControllerExec(gActiveBattler);
          gBattlescriptCurrInstr += 5;
      }
}

/** static void Cmd_jumpifnotfirstturn(void) */
export function Cmd_jumpifnotfirstturn(): any {
  let failJump: any = T1_READ_PTR(gBattlescriptCurrInstr + 1);

      if (gDisableStructs[gBattlerAttacker].isFirstTurn)
          gBattlescriptCurrInstr += 5;
      else
          gBattlescriptCurrInstr = failJump;
}

/** static void Cmd_nop(void) */
export function Cmd_nop(): any {
  gBattlescriptCurrInstr++;
}

/** bool8 UproarWakeUpCheck(u8 battler) */
export function UproarWakeUpCheck(battler: any): any {
  let i: any = null;

      for (i = 0; i < gBattlersCount; i++)
      {
          if (!(gBattleMons[i].status2 & STATUS2_UPROAR) || gBattleMons[battler].ability == ABILITY_SOUNDPROOF)
              continue;

          gBattleScripting.battler = i;

          if (gBattlerTarget == 0xFF)
              gBattlerTarget = i;
          else if (gBattlerTarget == i)
              gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_CANT_SLEEP_UPROAR;
          else
              gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_UPROAR_KEPT_AWAKE;

          break;
      }

      if (i == gBattlersCount)
          return FALSE;
      else
          return TRUE;
}

/** static void Cmd_jumpifcantmakeasleep(void) */
export function Cmd_jumpifcantmakeasleep(): any {
  let jumpPtr: any = T1_READ_PTR(gBattlescriptCurrInstr + 1);

      if (UproarWakeUpCheck(gBattlerTarget))
      {
          gBattlescriptCurrInstr = jumpPtr;
      }
      else if (gBattleMons[gBattlerTarget].ability == ABILITY_INSOMNIA
              || gBattleMons[gBattlerTarget].ability == ABILITY_VITAL_SPIRIT)
      {
          gLastUsedAbility = gBattleMons[gBattlerTarget].ability;
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_STAYED_AWAKE_USING;
          gBattlescriptCurrInstr = jumpPtr;
          RecordAbilityBattle(gBattlerTarget, gLastUsedAbility);
      }
      else
      {
          gBattlescriptCurrInstr += 5;
      }
}

/** static void Cmd_stockpile(void) */
export function Cmd_stockpile(): any {
  if (gDisableStructs[gBattlerAttacker].stockpileCounter == 3)
      {
          gMoveResultFlags |= MOVE_RESULT_MISSED;
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_CANT_STOCKPILE;
      }
      else
      {
          gDisableStructs[gBattlerAttacker].stockpileCounter++;

          PREPARE_BYTE_NUMBER_BUFFER(gBattleTextBuff1, 1, gDisableStructs[gBattlerAttacker].stockpileCounter)

          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_STOCKPILED;
      }
      gBattlescriptCurrInstr++;
}

/** static void Cmd_stockpiletobasedamage(void) */
export function Cmd_stockpiletobasedamage(): any {
  let jumpPtr: any = T1_READ_PTR(gBattlescriptCurrInstr + 1);
      if (gDisableStructs[gBattlerAttacker].stockpileCounter == 0)
      {
          gBattlescriptCurrInstr = jumpPtr;
      }
      else
      {
          if (gBattleCommunication[MISS_TYPE] != B_MSG_PROTECTED)
          {
              gBattleMoveDamage = CalculateBaseDamage(gBattleMons[gBattlerAttacker],gBattleMons[gBattlerTarget], gCurrentMove,
                                                      gSideStatuses[GET_BATTLER_SIDE(gBattlerTarget)], 0,
                                                      0, gBattlerAttacker, gBattlerTarget)
                                  * gDisableStructs[gBattlerAttacker].stockpileCounter;
              gBattleScripting.animTurn = gDisableStructs[gBattlerAttacker].stockpileCounter;

              if (gProtectStructs[gBattlerAttacker].helpingHand)
                  gBattleMoveDamage = gBattleMoveDamage * 15 / 10;
          }

          gDisableStructs[gBattlerAttacker].stockpileCounter = 0;
          gBattlescriptCurrInstr += 5;
      }
}

/** static void Cmd_stockpiletohpheal(void) */
export function Cmd_stockpiletohpheal(): any {
  let jumpPtr: any = T1_READ_PTR(gBattlescriptCurrInstr + 1);

      if (gDisableStructs[gBattlerAttacker].stockpileCounter == 0)
      {
          gBattlescriptCurrInstr = jumpPtr;
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_SWALLOW_FAILED;
      }
      else if (gBattleMons[gBattlerAttacker].maxHP == gBattleMons[gBattlerAttacker].hp)
      {
          gDisableStructs[gBattlerAttacker].stockpileCounter = 0;
          gBattlescriptCurrInstr = jumpPtr;
          gBattlerTarget = gBattlerAttacker;
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_SWALLOW_FULL_HP;
      }
      else
      {
          gBattleMoveDamage = gBattleMons[gBattlerAttacker].maxHP / (1 << (3 - gDisableStructs[gBattlerAttacker].stockpileCounter));

          if (gBattleMoveDamage == 0)
              gBattleMoveDamage = 1;
          gBattleMoveDamage *= -1;

          gBattleScripting.animTurn = gDisableStructs[gBattlerAttacker].stockpileCounter;
          gDisableStructs[gBattlerAttacker].stockpileCounter = 0;
          gBattlescriptCurrInstr += 5;
          gBattlerTarget = gBattlerAttacker;
      }
}

/** static void Cmd_negativedamage(void) */
export function Cmd_negativedamage(): any {
  gBattleMoveDamage = -(gHpDealt / 2);
      if (gBattleMoveDamage == 0)
          gBattleMoveDamage = -1;

      gBattlescriptCurrInstr++;
}

/** static u8 ChangeStatBuffs(s8 statValue, u8 statId, u8 flags, const u8 *BS_ptr) */
export function ChangeStatBuffs(statValue: any, statId: any, flags: any, BS_ptr: any): any {
  let certain: any = FALSE;
      let notProtectAffected: any = FALSE;
      let index: any = null;

      if (flags & MOVE_EFFECT_AFFECTS_USER)
          gActiveBattler = gBattlerAttacker;
      else
          gActiveBattler = gBattlerTarget;

      flags &= ~MOVE_EFFECT_AFFECTS_USER;

      if (flags & MOVE_EFFECT_CERTAIN)
          certain++;
      flags &= ~MOVE_EFFECT_CERTAIN;

      if (flags & STAT_CHANGE_NOT_PROTECT_AFFECTED)
          notProtectAffected++;
      flags &= ~STAT_CHANGE_NOT_PROTECT_AFFECTED;

      PREPARE_STAT_BUFFER(gBattleTextBuff1, statId)

      if (statValue <= -1)  
      {
          if (gSideTimers[GET_BATTLER_SIDE(gActiveBattler)].mistTimer
              && !certain && gCurrentMove != MOVE_CURSE)
          {
              if (flags == STAT_CHANGE_ALLOW_PTR)
              {
                  if (gSpecialStatuses[gActiveBattler].statLowered)
                  {
                      gBattlescriptCurrInstr = BS_ptr;
                  }
                  else
                  {
                      BattleScriptPush(BS_ptr);
                      gBattleScripting.battler = gActiveBattler;
                      gBattlescriptCurrInstr = BattleScript_MistProtected;
                      gSpecialStatuses[gActiveBattler].statLowered = 1;
                  }
              }
              return STAT_CHANGE_DIDNT_WORK;
          }
          else if (gCurrentMove != MOVE_CURSE
                   && notProtectAffected != TRUE && JumpIfMoveAffectedByProtect(0))
          {
              gBattlescriptCurrInstr = BattleScript_ButItFailed;
              return STAT_CHANGE_DIDNT_WORK;
          }
          else if ((gBattleMons[gActiveBattler].ability == ABILITY_CLEAR_BODY
                    || gBattleMons[gActiveBattler].ability == ABILITY_WHITE_SMOKE)
                   && !certain && gCurrentMove != MOVE_CURSE)
          {
              if (flags == STAT_CHANGE_ALLOW_PTR)
              {
                  if (gSpecialStatuses[gActiveBattler].statLowered)
                  {
                      gBattlescriptCurrInstr = BS_ptr;
                  }
                  else
                  {
                      BattleScriptPush(BS_ptr);
                      gBattleScripting.battler = gActiveBattler;
                      gBattlescriptCurrInstr = BattleScript_AbilityNoStatLoss;
                      gLastUsedAbility = gBattleMons[gActiveBattler].ability;
                      RecordAbilityBattle(gActiveBattler, gLastUsedAbility);
                      gSpecialStatuses[gActiveBattler].statLowered = 1;
                  }
              }
              return STAT_CHANGE_DIDNT_WORK;
          }
          else if (gBattleMons[gActiveBattler].ability == ABILITY_KEEN_EYE
                   && !certain && statId == STAT_ACC)
          {
              if (flags == STAT_CHANGE_ALLOW_PTR)
              {
                  BattleScriptPush(BS_ptr);
                  gBattleScripting.battler = gActiveBattler;
                  gBattlescriptCurrInstr = BattleScript_AbilityNoSpecificStatLoss;
                  gLastUsedAbility = gBattleMons[gActiveBattler].ability;
                  RecordAbilityBattle(gActiveBattler, gLastUsedAbility);
              }
              return STAT_CHANGE_DIDNT_WORK;
          }
          else if (gBattleMons[gActiveBattler].ability == ABILITY_HYPER_CUTTER
                   && !certain && statId == STAT_ATK)
          {
              if (flags == STAT_CHANGE_ALLOW_PTR)
              {
                  BattleScriptPush(BS_ptr);
                  gBattleScripting.battler = gActiveBattler;
                  gBattlescriptCurrInstr = BattleScript_AbilityNoSpecificStatLoss;
                  gLastUsedAbility = gBattleMons[gActiveBattler].ability;
                  RecordAbilityBattle(gActiveBattler, gLastUsedAbility);
              }
              return STAT_CHANGE_DIDNT_WORK;
          }
          else if (gBattleMons[gActiveBattler].ability == ABILITY_SHIELD_DUST && flags == 0)
          {
              return STAT_CHANGE_DIDNT_WORK;
          }
          else  
          {
              statValue = -GET_STAT_BUFF_VALUE(statValue);
              gBattleTextBuff2[0] = B_BUFF_PLACEHOLDER_BEGIN;
              index = 1;
              if (statValue == -2)
              {
                  gBattleTextBuff2[1] = B_BUFF_STRING;
                  gBattleTextBuff2[2] = STRINGID_STATHARSHLY;
                  gBattleTextBuff2[3] = STRINGID_STATHARSHLY >> 8;
                  index = 4;
              }
              gBattleTextBuff2[index++] = B_BUFF_STRING;
              gBattleTextBuff2[index++] = STRINGID_STATFELL;
              gBattleTextBuff2[index++] = STRINGID_STATFELL >> 8;
              gBattleTextBuff2[index] = B_BUFF_EOS;

              if (gBattleMons[gActiveBattler].statStages[statId] == MIN_STAT_STAGE)
                  gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_STAT_WONT_DECREASE;
              else
                  gBattleCommunication[MULTISTRING_CHOOSER] = (gBattlerTarget == gActiveBattler);  
          }
      }
      else  
      {
          statValue = GET_STAT_BUFF_VALUE(statValue);
          gBattleTextBuff2[0] = B_BUFF_PLACEHOLDER_BEGIN;
          index = 1;
          if (statValue == 2)
          {
              gBattleTextBuff2[1] = B_BUFF_STRING;
              gBattleTextBuff2[2] = STRINGID_STATSHARPLY;
              gBattleTextBuff2[3] = STRINGID_STATSHARPLY >> 8;
              index = 4;
          }
          gBattleTextBuff2[index++] = B_BUFF_STRING;
          gBattleTextBuff2[index++] = STRINGID_STATROSE;
          gBattleTextBuff2[index++] = STRINGID_STATROSE >> 8;
          gBattleTextBuff2[index] = B_BUFF_EOS;

          if (gBattleMons[gActiveBattler].statStages[statId] == MAX_STAT_STAGE)
              gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_STAT_WONT_INCREASE;
          else
              gBattleCommunication[MULTISTRING_CHOOSER] = (gBattlerTarget == gActiveBattler);  
      }

      gBattleMons[gActiveBattler].statStages[statId] += statValue;
      if (gBattleMons[gActiveBattler].statStages[statId] < MIN_STAT_STAGE)
          gBattleMons[gActiveBattler].statStages[statId] = MIN_STAT_STAGE;
      if (gBattleMons[gActiveBattler].statStages[statId] > MAX_STAT_STAGE)
          gBattleMons[gActiveBattler].statStages[statId] = MAX_STAT_STAGE;

      if (gBattleCommunication[MULTISTRING_CHOOSER] == B_MSG_STAT_WONT_INCREASE && flags & STAT_CHANGE_ALLOW_PTR)
          gMoveResultFlags |= MOVE_RESULT_MISSED;

      if (gBattleCommunication[MULTISTRING_CHOOSER] == B_MSG_STAT_WONT_INCREASE && !(flags & STAT_CHANGE_ALLOW_PTR))
          return STAT_CHANGE_DIDNT_WORK;

      return STAT_CHANGE_WORKED;
}

/** static void Cmd_statbuffchange(void) */
export function Cmd_statbuffchange(): any {
  let jumpPtr: any = T1_READ_PTR(gBattlescriptCurrInstr + 2);
      if (ChangeStatBuffs(gBattleScripting.statChanger & 0xF0, GET_STAT_BUFF_ID(gBattleScripting.statChanger), gBattlescriptCurrInstr[1], jumpPtr) == STAT_CHANGE_WORKED)
          gBattlescriptCurrInstr += 6;
}

/** static void Cmd_normalisebuffs(void) */
export function Cmd_normalisebuffs(): any {
  let i, j;

      for (i = 0; i < gBattlersCount; i++)
      {
          for (j = 0; j < NUM_BATTLE_STATS; j++)
              gBattleMons[i].statStages[j] = DEFAULT_STAT_STAGE;
      }

      gBattlescriptCurrInstr++;
}

/** static void Cmd_setbide(void) */
export function Cmd_setbide(): any {
  gBattleMons[gBattlerAttacker].status2 |= STATUS2_MULTIPLETURNS;
      gLockedMoves[gBattlerAttacker] = gCurrentMove;
      gBideDmg[gBattlerAttacker] = 0;
      gBattleMons[gBattlerAttacker].status2 |= STATUS2_BIDE_TURN(2);

      gBattlescriptCurrInstr++;
}

/** static void Cmd_confuseifrepeatingattackends(void) */
export function Cmd_confuseifrepeatingattackends(): any {
  if (!(gBattleMons[gBattlerAttacker].status2 & STATUS2_LOCK_CONFUSE))
          gBattleCommunication[MOVE_EFFECT_BYTE] = (MOVE_EFFECT_THRASH | MOVE_EFFECT_AFFECTS_USER);

      gBattlescriptCurrInstr++;
}

/** static void Cmd_setmultihitcounter(void) */
export function Cmd_setmultihitcounter(): any {
  if (gBattlescriptCurrInstr[1])
      {
          gMultiHitCounter = gBattlescriptCurrInstr[1];
      }
      else
      {
          gMultiHitCounter = Random() & 3;
          if (gMultiHitCounter > 1)
              gMultiHitCounter = (Random() & 3) + 2;
          else
              gMultiHitCounter += 2;
      }

      gBattlescriptCurrInstr += 2;
}

/** static void Cmd_initmultihitstring(void) */
export function Cmd_initmultihitstring(): any {
  PREPARE_BYTE_NUMBER_BUFFER(gBattleScripting.multihitString, 1, 0)

      gBattlescriptCurrInstr++;
}

/** static bool8 TryDoForceSwitchOut(void) */
export function TryDoForceSwitchOut(): any {
  if (gBattleMons[gBattlerAttacker].level >= gBattleMons[gBattlerTarget].level)
      {
          MEM_WRITE((gBattleStruct.battlerPartyIndexes + gBattlerTarget), gBattlerPartyIndexes[gBattlerTarget]);
      }
      else
      {
          let random: any = Random() & 0xFF;
          if (((random * (gBattleMons[gBattlerAttacker].level + gBattleMons[gBattlerTarget].level) >> 8) + 1) <= (gBattleMons[gBattlerTarget].level / 4))
          {
              gBattlescriptCurrInstr = T1_READ_PTR(gBattlescriptCurrInstr + 1);
              return FALSE;
          }
          MEM_WRITE((gBattleStruct.battlerPartyIndexes + gBattlerTarget), gBattlerPartyIndexes[gBattlerTarget]);
      }

      gBattlescriptCurrInstr = BattleScript_SuccessForceOut;
      return TRUE;
}

/** static void Cmd_forcerandomswitch(void) */
export function Cmd_forcerandomswitch(): any {
  let i: any = null;
      let battler1PartyId: any = 0;
      let battler2PartyId: any = 0;

      let firstMonId: any = null;
      let lastMonId: any = 0;
      let monsCount: any = null;
      let party: any = NULL;
      let validMons: any = 0;
      let minNeeded: any = null;

      if ((gBattleTypeFlags & BATTLE_TYPE_TRAINER))
      {
          if (GetBattlerSide(gBattlerTarget) == B_SIDE_PLAYER)
              party = gPlayerParty;
          else
              party = gEnemyParty;

          if ((gBattleTypeFlags & BATTLE_TYPE_BATTLE_TOWER && gBattleTypeFlags & BATTLE_TYPE_LINK)
              || (gBattleTypeFlags & BATTLE_TYPE_BATTLE_TOWER && gBattleTypeFlags & BATTLE_TYPE_RECORDED_LINK)
              || (gBattleTypeFlags & BATTLE_TYPE_INGAME_PARTNER))
          {
              if ((gBattlerTarget & BIT_FLANK) != B_FLANK_LEFT)
              {
                  firstMonId = PARTY_SIZE / 2;
                  lastMonId = PARTY_SIZE - 1;
              }
              else
              {
                  firstMonId = 0;
                  lastMonId = PARTY_SIZE / 2 - 1;
              }
              monsCount = PARTY_SIZE / 2;
              minNeeded = 1;
              battler2PartyId = gBattlerPartyIndexes[gBattlerTarget];
              battler1PartyId = gBattlerPartyIndexes[BATTLE_PARTNER(gBattlerTarget)];
          }
          else if ((gBattleTypeFlags & BATTLE_TYPE_MULTI && gBattleTypeFlags & BATTLE_TYPE_LINK)
                   || (gBattleTypeFlags & BATTLE_TYPE_MULTI && gBattleTypeFlags & BATTLE_TYPE_RECORDED_LINK))
          {
              if (GetLinkTrainerFlankId(GetBattlerMultiplayerId(gBattlerTarget)) == B_FLANK_RIGHT)
              {
                  firstMonId = PARTY_SIZE / 2;
                  lastMonId = PARTY_SIZE - 1;
              }
              else
              {
                  firstMonId = 0;
                  lastMonId = PARTY_SIZE / 2 - 1;
              }
              monsCount = PARTY_SIZE / 2;
              minNeeded = 1;
              battler2PartyId = gBattlerPartyIndexes[gBattlerTarget];
              battler1PartyId = gBattlerPartyIndexes[BATTLE_PARTNER(gBattlerTarget)];
          }
          else if (gBattleTypeFlags & BATTLE_TYPE_TWO_OPPONENTS)
          {
              if (GetBattlerSide(gBattlerTarget) == B_SIDE_PLAYER)
              {
                  firstMonId = 0;
                  lastMonId = PARTY_SIZE - 1;
                  monsCount = PARTY_SIZE;
                  minNeeded = 2;  
              }
              else
              {
                  if ((gBattlerTarget & BIT_FLANK) != B_FLANK_LEFT)
                  {
                      firstMonId = PARTY_SIZE / 2;
                      lastMonId = PARTY_SIZE - 1;
                  }
                  else
                  {
                      firstMonId = 0;
                      lastMonId = PARTY_SIZE / 2 - 1;
                  }
                  monsCount = PARTY_SIZE / 2;
                  minNeeded = 1;
              }
              battler2PartyId = gBattlerPartyIndexes[gBattlerTarget];
              battler1PartyId = gBattlerPartyIndexes[BATTLE_PARTNER(gBattlerTarget)];
          }
          else if (gBattleTypeFlags & BATTLE_TYPE_DOUBLE)
          {
              firstMonId = 0;
              lastMonId = PARTY_SIZE - 1;
              monsCount = PARTY_SIZE;
              minNeeded = 2;
              battler2PartyId = gBattlerPartyIndexes[gBattlerTarget];
              battler1PartyId = gBattlerPartyIndexes[BATTLE_PARTNER(gBattlerTarget)];
          }
          else
          {
              firstMonId = 0;
              lastMonId = PARTY_SIZE - 1;
              monsCount = PARTY_SIZE;
              minNeeded = 1;
              battler2PartyId = gBattlerPartyIndexes[gBattlerTarget];  
              battler1PartyId = gBattlerPartyIndexes[gBattlerTarget];
          }

          for (i = firstMonId; i < lastMonId; i++)
          {
              if (GetMonData(party[i], MON_DATA_SPECIES) != SPECIES_NONE
               && !GetMonData(party[i], MON_DATA_IS_EGG)
               && GetMonData(party[i], MON_DATA_HP) != 0)
               {
                   validMons++;
               }
          }

          if (validMons <= minNeeded)
          {
              gBattlescriptCurrInstr = T1_READ_PTR(gBattlescriptCurrInstr + 1);
          }
          else
          {
              if (TryDoForceSwitchOut())
              {
                  do
                  {
                      do
                      {
                          i = Random() % monsCount;
                          i += firstMonId;
                      }
                      while (i == battler2PartyId || i == battler1PartyId);
                  } while (GetMonData(party[i], MON_DATA_SPECIES) == SPECIES_NONE
                         || GetMonData(party[i], MON_DATA_IS_EGG) == TRUE
                         || GetMonData(party[i], MON_DATA_HP) == 0);  
              }
              MEM_WRITE((gBattleStruct.monToSwitchIntoId + gBattlerTarget), i);

              if (!IsMultiBattle())
                  SwitchPartyOrder(gBattlerTarget);

              if ((gBattleTypeFlags & BATTLE_TYPE_LINK && gBattleTypeFlags & BATTLE_TYPE_BATTLE_TOWER)
                  || (gBattleTypeFlags & BATTLE_TYPE_LINK && gBattleTypeFlags & BATTLE_TYPE_MULTI)
                  || (gBattleTypeFlags & BATTLE_TYPE_RECORDED_LINK && gBattleTypeFlags & BATTLE_TYPE_BATTLE_TOWER)
                  || (gBattleTypeFlags & BATTLE_TYPE_RECORDED_LINK && gBattleTypeFlags & BATTLE_TYPE_MULTI))
              {
                  SwitchPartyOrderLinkMulti(gBattlerTarget, i, 0);
                  SwitchPartyOrderLinkMulti(BATTLE_PARTNER(gBattlerTarget), i, 1);
              }

              if (gBattleTypeFlags & BATTLE_TYPE_INGAME_PARTNER)
                  SwitchPartyOrderInGameMulti(gBattlerTarget, i);
              }
          }
}

/** static void Cmd_tryconversiontypechange(void) */
export function Cmd_tryconversiontypechange(): any {
  let validMoves: any = 0;
      let moveChecked: any = null;
      let moveType: any = null;

      while (validMoves < MAX_MON_MOVES)
      {
          if (gBattleMons[gBattlerAttacker].moves[validMoves] == MOVE_NONE)
              break;

          validMoves++;
      }

      for (moveChecked = 0; moveChecked < validMoves; moveChecked++)
      {
          moveType = gBattleMoves[gBattleMons[gBattlerAttacker].moves[moveChecked]].type;

          if (moveType == TYPE_MYSTERY)
          {
              if (IS_BATTLER_OF_TYPE(gBattlerAttacker, TYPE_GHOST))
                  moveType = TYPE_GHOST;
              else
                  moveType = TYPE_NORMAL;
          }
          if (moveType != gBattleMons[gBattlerAttacker].types[0]
              && moveType != gBattleMons[gBattlerAttacker].types[1])
          {
              break;
          }
      }

      if (moveChecked == validMoves)
      {
          gBattlescriptCurrInstr = T1_READ_PTR(gBattlescriptCurrInstr + 1);
      }
      else
      {
          do
          {
              while ((moveChecked = MOD(Random(), MAX_MON_MOVES)) >= validMoves);

              moveType = gBattleMoves[gBattleMons[gBattlerAttacker].moves[moveChecked]].type;

              if (moveType == TYPE_MYSTERY)
              {
                  if (IS_BATTLER_OF_TYPE(gBattlerAttacker, TYPE_GHOST))
                      moveType = TYPE_GHOST;
                  else
                      moveType = TYPE_NORMAL;
              }
          }
          while (moveType == gBattleMons[gBattlerAttacker].types[0] || moveType == gBattleMons[gBattlerAttacker].types[1]);

          SET_BATTLER_TYPE(gBattlerAttacker, moveType);
          PREPARE_TYPE_BUFFER(gBattleTextBuff1, moveType);

          gBattlescriptCurrInstr += 5;
      }
}

/** static void Cmd_givepaydaymoney(void) */
export function Cmd_givepaydaymoney(): any {
  if (!(gBattleTypeFlags & (BATTLE_TYPE_LINK | BATTLE_TYPE_RECORDED_LINK)) && gPaydayMoney != 0)
      {
          let bonusMoney: any = gPaydayMoney * gBattleStruct.moneyMultiplier;
          AddMoney(gSaveBlock1Ptr.money, bonusMoney);

          PREPARE_HWORD_NUMBER_BUFFER(gBattleTextBuff1, 5, bonusMoney)

          BattleScriptPush(gBattlescriptCurrInstr + 1);
          gBattlescriptCurrInstr = BattleScript_PrintPayDayMoneyString;
      }
      else
      {
          gBattlescriptCurrInstr++;
      }
}

/** static void Cmd_setlightscreen(void) */
export function Cmd_setlightscreen(): any {
  if (gSideStatuses[GET_BATTLER_SIDE(gBattlerAttacker)] & SIDE_STATUS_LIGHTSCREEN)
      {
          gMoveResultFlags |= MOVE_RESULT_MISSED;
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_SIDE_STATUS_FAILED;
      }
      else
      {
          gSideStatuses[GET_BATTLER_SIDE(gBattlerAttacker)] |= SIDE_STATUS_LIGHTSCREEN;
          gSideTimers[GET_BATTLER_SIDE(gBattlerAttacker)].lightscreenTimer = 5;
          gSideTimers[GET_BATTLER_SIDE(gBattlerAttacker)].lightscreenBattlerId = gBattlerAttacker;

          if (gBattleTypeFlags & BATTLE_TYPE_DOUBLE && CountAliveMonsInBattle(BATTLE_ALIVE_ATK_SIDE) == 2)
              gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_SET_LIGHTSCREEN_DOUBLE;
          else
              gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_SET_LIGHTSCREEN_SINGLE;
      }

      gBattlescriptCurrInstr++;
}

/** static void Cmd_tryKO(void) */
export function Cmd_tryKO(): any {
  let holdEffect, param;

      if (gBattleMons[gBattlerTarget].item == ITEM_ENIGMA_BERRY)
      {
         holdEffect = gEnigmaBerries[gBattlerTarget].holdEffect;
         param = gEnigmaBerries[gBattlerTarget].holdEffectParam;
      }
      else
      {
          holdEffect = GetItemHoldEffect(gBattleMons[gBattlerTarget].item);
          param = GetItemHoldEffectParam(gBattleMons[gBattlerTarget].item);
      }

      gPotentialItemEffectBattler = gBattlerTarget;

      if (holdEffect == HOLD_EFFECT_FOCUS_BAND && (Random() % 100) < param)
      {
          RecordItemEffectBattle(gBattlerTarget, HOLD_EFFECT_FOCUS_BAND);
          gSpecialStatuses[gBattlerTarget].focusBanded = 1;
      }

      if (gBattleMons[gBattlerTarget].ability == ABILITY_STURDY)
      {
          gMoveResultFlags |= MOVE_RESULT_MISSED;
          gLastUsedAbility = ABILITY_STURDY;
          gBattlescriptCurrInstr = BattleScript_SturdyPreventsOHKO;
          RecordAbilityBattle(gBattlerTarget, ABILITY_STURDY);
      }
      else
      {
          let chance: any = null;
          if (!(gStatuses3[gBattlerTarget] & STATUS3_ALWAYS_HITS))
          {
              chance = gBattleMoves[gCurrentMove].accuracy + (gBattleMons[gBattlerAttacker].level - gBattleMons[gBattlerTarget].level);
              if (Random() % 100 + 1 < chance && gBattleMons[gBattlerAttacker].level >= gBattleMons[gBattlerTarget].level)
                  chance = TRUE;
              else
                  chance = FALSE;
          }
          else if (gDisableStructs[gBattlerTarget].battlerWithSureHit == gBattlerAttacker
                   && gBattleMons[gBattlerAttacker].level >= gBattleMons[gBattlerTarget].level)
          {
              chance = TRUE;
          }
          else
          {
              chance = gBattleMoves[gCurrentMove].accuracy + (gBattleMons[gBattlerAttacker].level - gBattleMons[gBattlerTarget].level);
              if (Random() % 100 + 1 < chance && gBattleMons[gBattlerAttacker].level >= gBattleMons[gBattlerTarget].level)
                  chance = TRUE;
              else
                  chance = FALSE;
          }
          if (chance)
          {
              if (gProtectStructs[gBattlerTarget].endured)
              {
                  gBattleMoveDamage = gBattleMons[gBattlerTarget].hp - 1;
                  gMoveResultFlags |= MOVE_RESULT_FOE_ENDURED;
              }
              else if (gSpecialStatuses[gBattlerTarget].focusBanded)
              {
                  gBattleMoveDamage = gBattleMons[gBattlerTarget].hp - 1;
                  gMoveResultFlags |= MOVE_RESULT_FOE_HUNG_ON;
                  gLastUsedItem = gBattleMons[gBattlerTarget].item;
              }
              else
              {
                  gBattleMoveDamage = gBattleMons[gBattlerTarget].hp;
                  gMoveResultFlags |= MOVE_RESULT_ONE_HIT_KO;
              }
              gBattlescriptCurrInstr += 5;
          }
          else
          {
              gMoveResultFlags |= MOVE_RESULT_MISSED;
              if (gBattleMons[gBattlerAttacker].level >= gBattleMons[gBattlerTarget].level)
                  gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_KO_MISS;
              else
                  gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_KO_UNAFFECTED;
              gBattlescriptCurrInstr = T1_READ_PTR(gBattlescriptCurrInstr + 1);
          }
      }
}

/** static void Cmd_damagetohalftargethp(void) */
export function Cmd_damagetohalftargethp(): any {
  gBattleMoveDamage = gBattleMons[gBattlerTarget].hp / 2;
      if (gBattleMoveDamage == 0)
          gBattleMoveDamage = 1;

      gBattlescriptCurrInstr++;
}

/** static void Cmd_setsandstorm(void) */
export function Cmd_setsandstorm(): any {
  if (gBattleWeather & B_WEATHER_SANDSTORM)
      {
          gMoveResultFlags |= MOVE_RESULT_MISSED;
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_WEATHER_FAILED;
      }
      else
      {
          gBattleWeather = B_WEATHER_SANDSTORM_TEMPORARY;
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_STARTED_SANDSTORM;
          gWishFutureKnock.weatherDuration = 5;
      }
      gBattlescriptCurrInstr++;
}

/** static void Cmd_weatherdamage(void) */
export function Cmd_weatherdamage(): any {
  if (WEATHER_HAS_EFFECT)
      {
          if (gBattleWeather & B_WEATHER_SANDSTORM)
          {
              if (gBattleMons[gBattlerAttacker].types[0] != TYPE_ROCK
                  && gBattleMons[gBattlerAttacker].types[0] != TYPE_STEEL
                  && gBattleMons[gBattlerAttacker].types[0] != TYPE_GROUND
                  && gBattleMons[gBattlerAttacker].types[1] != TYPE_ROCK
                  && gBattleMons[gBattlerAttacker].types[1] != TYPE_STEEL
                  && gBattleMons[gBattlerAttacker].types[1] != TYPE_GROUND
                  && gBattleMons[gBattlerAttacker].ability != ABILITY_SAND_VEIL
                  && !(gStatuses3[gBattlerAttacker] & STATUS3_UNDERGROUND)
                  && !(gStatuses3[gBattlerAttacker] & STATUS3_UNDERWATER))
              {
                  gBattleMoveDamage = gBattleMons[gBattlerAttacker].maxHP / 16;
                  if (gBattleMoveDamage == 0)
                      gBattleMoveDamage = 1;
              }
              else
              {
                  gBattleMoveDamage = 0;
              }
          }
          if (gBattleWeather & B_WEATHER_HAIL)
          {
              if (!IS_BATTLER_OF_TYPE(gBattlerAttacker, TYPE_ICE)
                  && !(gStatuses3[gBattlerAttacker] & STATUS3_UNDERGROUND)
                  && !(gStatuses3[gBattlerAttacker] & STATUS3_UNDERWATER))
              {
                  gBattleMoveDamage = gBattleMons[gBattlerAttacker].maxHP / 16;
                  if (gBattleMoveDamage == 0)
                      gBattleMoveDamage = 1;
              }
              else
              {
                  gBattleMoveDamage = 0;
              }
          }
      }
      else
      {
          gBattleMoveDamage = 0;
      }

      if (gAbsentBattlerFlags & gBitTable[gBattlerAttacker])
          gBattleMoveDamage = 0;

      gBattlescriptCurrInstr++;
}

/** static void Cmd_tryinfatuating(void) */
export function Cmd_tryinfatuating(): any {
  let monAttacker, monTarget;
      let speciesAttacker, speciesTarget;
      let personalityAttacker, personalityTarget;

      if (GetBattlerSide(gBattlerAttacker) == B_SIDE_PLAYER)
          monAttacker =gPlayerParty[gBattlerPartyIndexes[gBattlerAttacker]];
      else
          monAttacker =gEnemyParty[gBattlerPartyIndexes[gBattlerAttacker]];

      if (GetBattlerSide(gBattlerTarget) == B_SIDE_PLAYER)
          monTarget =gPlayerParty[gBattlerPartyIndexes[gBattlerTarget]];
      else
          monTarget =gEnemyParty[gBattlerPartyIndexes[gBattlerTarget]];

      speciesAttacker = GetMonData(monAttacker, MON_DATA_SPECIES);
      personalityAttacker = GetMonData(monAttacker, MON_DATA_PERSONALITY);

      speciesTarget = GetMonData(monTarget, MON_DATA_SPECIES);
      personalityTarget = GetMonData(monTarget, MON_DATA_PERSONALITY);

      if (gBattleMons[gBattlerTarget].ability == ABILITY_OBLIVIOUS)
      {
          gBattlescriptCurrInstr = BattleScript_ObliviousPreventsAttraction;
          gLastUsedAbility = ABILITY_OBLIVIOUS;
          RecordAbilityBattle(gBattlerTarget, ABILITY_OBLIVIOUS);
      }
      else
      {
          if (GetGenderFromSpeciesAndPersonality(speciesAttacker, personalityAttacker) == GetGenderFromSpeciesAndPersonality(speciesTarget, personalityTarget)
              || gBattleMons[gBattlerTarget].status2 & STATUS2_INFATUATION
              || GetGenderFromSpeciesAndPersonality(speciesAttacker, personalityAttacker) == MON_GENDERLESS
              || GetGenderFromSpeciesAndPersonality(speciesTarget, personalityTarget) == MON_GENDERLESS)
          {
              gBattlescriptCurrInstr = T1_READ_PTR(gBattlescriptCurrInstr + 1);
          }
          else
          {
              gBattleMons[gBattlerTarget].status2 |= STATUS2_INFATUATED_WITH(gBattlerAttacker);
              gBattlescriptCurrInstr += 5;
          }
      }
}

/** static void Cmd_updatestatusicon(void) */
export function Cmd_updatestatusicon(): any {
  if (gBattleControllerExecFlags)
          return;

      if (gBattlescriptCurrInstr[1] != BS_ATTACKER_WITH_PARTNER)
      {
          gActiveBattler = GetBattlerForBattleScript(gBattlescriptCurrInstr[1]);
          BtlController_EmitStatusIconUpdate(B_COMM_TO_CONTROLLER, gBattleMons[gActiveBattler].status1, gBattleMons[gActiveBattler].status2);
          MarkBattlerForControllerExec(gActiveBattler);
          gBattlescriptCurrInstr += 2;
      }
      else
      {
          gActiveBattler = gBattlerAttacker;
          if (!(gAbsentBattlerFlags & gBitTable[gActiveBattler]))
          {
              BtlController_EmitStatusIconUpdate(B_COMM_TO_CONTROLLER, gBattleMons[gActiveBattler].status1, gBattleMons[gActiveBattler].status2);
              MarkBattlerForControllerExec(gActiveBattler);
          }
          if ((gBattleTypeFlags & BATTLE_TYPE_DOUBLE))
          {
              gActiveBattler = GetBattlerAtPosition(BATTLE_PARTNER(GetBattlerPosition(gBattlerAttacker)));
              if (!(gAbsentBattlerFlags & gBitTable[gActiveBattler]))
              {
                  BtlController_EmitStatusIconUpdate(B_COMM_TO_CONTROLLER, gBattleMons[gActiveBattler].status1, gBattleMons[gActiveBattler].status2);
                  MarkBattlerForControllerExec(gActiveBattler);
              }
          }
          gBattlescriptCurrInstr += 2;
      }
}

/** static void Cmd_setmist(void) */
export function Cmd_setmist(): any {
  if (gSideTimers[GET_BATTLER_SIDE(gBattlerAttacker)].mistTimer)
      {
          gMoveResultFlags |= MOVE_RESULT_FAILED;
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_MIST_FAILED;
      }
      else
      {
          gSideTimers[GET_BATTLER_SIDE(gBattlerAttacker)].mistTimer = 5;
          gSideTimers[GET_BATTLER_SIDE(gBattlerAttacker)].mistBattlerId = gBattlerAttacker;
          gSideStatuses[GET_BATTLER_SIDE(gBattlerAttacker)] |= SIDE_STATUS_MIST;
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_SET_MIST;
      }
      gBattlescriptCurrInstr++;
}

