/** static void Cmd_transformdataexecution(void) */
export function Cmd_transformdataexecution(): any {
  gChosenMove = MOVE_UNAVAILABLE;
      gBattlescriptCurrInstr++;
      if (gBattleMons[gBattlerTarget].status2 & STATUS2_TRANSFORMED
          || gStatuses3[gBattlerTarget] & STATUS3_SEMI_INVULNERABLE)
      {
          gMoveResultFlags |= MOVE_RESULT_FAILED;
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_TRANSFORM_FAILED;
      }
      else
      {
          let i: any = null;
          let battleMonAttacker, battleMonTarget;

          gBattleMons[gBattlerAttacker].status2 |= STATUS2_TRANSFORMED;
          gDisableStructs[gBattlerAttacker].disabledMove = MOVE_NONE;
          gDisableStructs[gBattlerAttacker].disableTimer = 0;
          gDisableStructs[gBattlerAttacker].transformedMonPersonality = gBattleMons[gBattlerTarget].personality;
          gDisableStructs[gBattlerAttacker].mimickedMoves = 0;

          PREPARE_SPECIES_BUFFER(gBattleTextBuff1, gBattleMons[gBattlerTarget].species)

          battleMonAttacker = (gBattleMons[gBattlerAttacker]);
          battleMonTarget = (gBattleMons[gBattlerTarget]);

          for (i = 0; i < 0; i++)
              battleMonAttacker[i] = battleMonTarget[i];

          for (i = 0; i < MAX_MON_MOVES; i++)
          {
              if (gBattleMoves[gBattleMons[gBattlerAttacker].moves[i]].pp < 5)
                  gBattleMons[gBattlerAttacker].pp[i] = gBattleMoves[gBattleMons[gBattlerAttacker].moves[i]].pp;
              else
                  gBattleMons[gBattlerAttacker].pp[i] = 5;
          }

          gActiveBattler = gBattlerAttacker;
          BtlController_EmitResetActionMoveSelection(B_COMM_TO_CONTROLLER, RESET_MOVE_SELECTION);
          MarkBattlerForControllerExec(gActiveBattler);
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_TRANSFORMED;
      }
}

/** static void Cmd_setsubstitute(void) */
export function Cmd_setsubstitute(): any {
  let hp: any = gBattleMons[gBattlerAttacker].maxHP / 4;
      if (gBattleMons[gBattlerAttacker].maxHP / 4 == 0)
          hp = 1;

      if (gBattleMons[gBattlerAttacker].hp <= hp)
      {
          gBattleMoveDamage = 0;
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_SUBSTITUTE_FAILED;
      }
      else
      {
          gBattleMoveDamage = gBattleMons[gBattlerAttacker].maxHP / 4;  
          if (gBattleMoveDamage == 0)
              gBattleMoveDamage = 1;

          gBattleMons[gBattlerAttacker].status2 |= STATUS2_SUBSTITUTE;
          gBattleMons[gBattlerAttacker].status2 &= ~STATUS2_WRAPPED;
          gDisableStructs[gBattlerAttacker].substituteHP = gBattleMoveDamage;
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_SET_SUBSTITUTE;
          gHitMarker |= HITMARKER_IGNORE_SUBSTITUTE;
      }

      gBattlescriptCurrInstr++;
}

/** static bool8 IsMoveUncopyableByMimic(u16 move) */
export function IsMoveUncopyableByMimic(move: any): any {
  let i: any = null;
      for (i = 0; sMovesForbiddenToCopy[i] != MIMIC_FORBIDDEN_END
                  && sMovesForbiddenToCopy[i] != move; i++);

      return (sMovesForbiddenToCopy[i] != MIMIC_FORBIDDEN_END);
}

/** static void Cmd_mimicattackcopy(void) */
export function Cmd_mimicattackcopy(): any {
  gChosenMove = MOVE_UNAVAILABLE;

      if (IsMoveUncopyableByMimic(gLastMoves[gBattlerTarget])
          || gBattleMons[gBattlerAttacker].status2 & STATUS2_TRANSFORMED
          || gLastMoves[gBattlerTarget] == MOVE_NONE
          || gLastMoves[gBattlerTarget] == MOVE_UNAVAILABLE)
      {
          gBattlescriptCurrInstr = T1_READ_PTR(gBattlescriptCurrInstr + 1);
      }
      else
      {
          let i: any = null;

          for (i = 0; i < MAX_MON_MOVES; i++)
          {
              if (gBattleMons[gBattlerAttacker].moves[i] == gLastMoves[gBattlerTarget])
                  break;
          }

          if (i == MAX_MON_MOVES)
          {
              gBattleMons[gBattlerAttacker].moves[gCurrMovePos] = gLastMoves[gBattlerTarget];
              if (gBattleMoves[gLastMoves[gBattlerTarget]].pp < 5)
                  gBattleMons[gBattlerAttacker].pp[gCurrMovePos] = gBattleMoves[gLastMoves[gBattlerTarget]].pp;
              else
                  gBattleMons[gBattlerAttacker].pp[gCurrMovePos] = 5;

              PREPARE_MOVE_BUFFER(gBattleTextBuff1, gLastMoves[gBattlerTarget])

              gDisableStructs[gBattlerAttacker].mimickedMoves |= gBitTable[gCurrMovePos];
              gBattlescriptCurrInstr += 5;
          }
          else
          {
              gBattlescriptCurrInstr = T1_READ_PTR(gBattlescriptCurrInstr + 1);
          }
      }
}

/** static void Cmd_metronome(void) */
export function Cmd_metronome(): any {
  while (TRUE)
      {
          let i: any = null;
           
           
           
           
          gCurrentMove = (Random() & 0x1FF) + 1;
          if (gCurrentMove >= MOVES_COUNT)
              continue;

          for (i = 0; i < MAX_MON_MOVES; i++);  

          i = -1;
          while (TRUE)
          {
              i++;
              if (sMovesForbiddenToCopy[i] == gCurrentMove)
                  break;
              if (sMovesForbiddenToCopy[i] == METRONOME_FORBIDDEN_END)
                  break;
          }

          if (sMovesForbiddenToCopy[i] == METRONOME_FORBIDDEN_END)
          {
              gHitMarker &= ~HITMARKER_ATTACKSTRING_PRINTED;
              gBattlescriptCurrInstr = gBattleScriptsForMoveEffects[gBattleMoves[gCurrentMove].effect];
              gBattlerTarget = GetMoveTarget(gCurrentMove, NO_TARGET_OVERRIDE);
              return;
          }
      }
}

