/** static void Cmd_handleballthrow(void) */
export function Cmd_handleballthrow(): any {
  let ballMultiplier: any = 0;

      if (gBattleControllerExecFlags)
          return;

      gActiveBattler = gBattlerAttacker;
      gBattlerTarget = BATTLE_OPPOSITE(gBattlerAttacker);

      if (gBattleTypeFlags & BATTLE_TYPE_TRAINER)
      {
          BtlController_EmitBallThrowAnim(B_COMM_TO_CONTROLLER, BALL_TRAINER_BLOCK);
          MarkBattlerForControllerExec(gActiveBattler);
          gBattlescriptCurrInstr = BattleScript_TrainerBallBlock;
      }
      else if (gBattleTypeFlags & BATTLE_TYPE_WALLY_TUTORIAL)
      {
          BtlController_EmitBallThrowAnim(B_COMM_TO_CONTROLLER, BALL_3_SHAKES_SUCCESS);
          MarkBattlerForControllerExec(gActiveBattler);
          gBattlescriptCurrInstr = BattleScript_WallyBallThrow;
      }
      else
      {
          let odds: any = null;
          let catchRate: any = null;

          if (gLastUsedItem == ITEM_SAFARI_BALL)
              catchRate = gBattleStruct.safariCatchFactor * 1275 / 100;
          else
              catchRate = gSpeciesInfo[gBattleMons[gBattlerTarget].species].catchRate;

          if (gLastUsedItem > ITEM_SAFARI_BALL)
          {
              switch (gLastUsedItem)
              {
              case ITEM_NET_BALL:
                  if (IS_BATTLER_OF_TYPE(gBattlerTarget, TYPE_WATER) || IS_BATTLER_OF_TYPE(gBattlerTarget, TYPE_BUG))
                      ballMultiplier = 30;
                  else
                      ballMultiplier = 10;
                  break;
              case ITEM_DIVE_BALL:
                  if (GetCurrentMapType() == MAP_TYPE_UNDERWATER)
                      ballMultiplier = 35;
                  else
                      ballMultiplier = 10;
                  break;
              case ITEM_NEST_BALL:
                  if (gBattleMons[gBattlerTarget].level < 40)
                  {
                      ballMultiplier = 40 - gBattleMons[gBattlerTarget].level;
                      if (ballMultiplier <= 9)
                          ballMultiplier = 10;
                  }
                  else
                  {
                      ballMultiplier = 10;
                  }
                  break;
              case ITEM_REPEAT_BALL:
                  if (GetSetPokedexFlag(SpeciesToNationalPokedexNum(gBattleMons[gBattlerTarget].species), FLAG_GET_CAUGHT))
                      ballMultiplier = 30;
                  else
                      ballMultiplier = 10;
                  break;
              case ITEM_TIMER_BALL:
                  ballMultiplier = gBattleResults.battleTurnCounter + 10;
                  if (ballMultiplier > 40)
                      ballMultiplier = 40;
                  break;
              case ITEM_LUXURY_BALL:
              case ITEM_PREMIER_BALL:
                  ballMultiplier = 10;
                  break;
              }
          }
          else
          {
              ballMultiplier = sBallCatchBonuses[gLastUsedItem - ITEM_ULTRA_BALL];
          }

          odds = (catchRate * ballMultiplier / 10)
              (gBattleMons[gBattlerTarget].maxHP * 3 - gBattleMons[gBattlerTarget].hp * 2)
              / (3 * gBattleMons[gBattlerTarget].maxHP);

          if (gBattleMons[gBattlerTarget].status1 & (STATUS1_SLEEP | STATUS1_FREEZE))
              odds *= 2;
          if (gBattleMons[gBattlerTarget].status1 & (STATUS1_POISON | STATUS1_BURN | STATUS1_PARALYSIS | STATUS1_TOXIC_POISON))
              odds = (odds * 15) / 10;

          if (gLastUsedItem != ITEM_SAFARI_BALL)
          {
              if (gLastUsedItem == ITEM_MASTER_BALL)
              {
                  gBattleResults.usedMasterBall = TRUE;
              }
              else
              {
                  if (gBattleResults.catchAttempts[gLastUsedItem - ITEM_ULTRA_BALL] < 255)
                      gBattleResults.catchAttempts[gLastUsedItem - ITEM_ULTRA_BALL]++;
              }
          }

          if (odds > 254)  
          {
              BtlController_EmitBallThrowAnim(B_COMM_TO_CONTROLLER, BALL_3_SHAKES_SUCCESS);
              MarkBattlerForControllerExec(gActiveBattler);
              gBattlescriptCurrInstr = BattleScript_SuccessBallThrow;
              SetMonData(gEnemyParty[gBattlerPartyIndexes[gBattlerTarget]], MON_DATA_POKEBALL,gLastUsedItem);

              if (CalculatePlayerPartyCount() == PARTY_SIZE)
                  gBattleCommunication[MULTISTRING_CHOOSER] = 0;
              else
                  gBattleCommunication[MULTISTRING_CHOOSER] = 1;
          }
          else  
          {
              let shakes: any = null;

              odds = Sqrt(Sqrt(16711680 / odds));
              odds = 1048560 / odds;

              for (shakes = 0; shakes < BALL_3_SHAKES_SUCCESS && Random() < odds; shakes++);

              if (gLastUsedItem == ITEM_MASTER_BALL)
                  shakes = BALL_3_SHAKES_SUCCESS;  

              BtlController_EmitBallThrowAnim(B_COMM_TO_CONTROLLER, shakes);
              MarkBattlerForControllerExec(gActiveBattler);

              if (shakes == BALL_3_SHAKES_SUCCESS)  
              {
                  gBattlescriptCurrInstr = BattleScript_SuccessBallThrow;
                  SetMonData(gEnemyParty[gBattlerPartyIndexes[gBattlerTarget]], MON_DATA_POKEBALL,gLastUsedItem);

                  if (CalculatePlayerPartyCount() == PARTY_SIZE)
                      gBattleCommunication[MULTISTRING_CHOOSER] = 0;
                  else
                      gBattleCommunication[MULTISTRING_CHOOSER] = 1;
              }
              else  
              {
                  gBattleCommunication[MULTISTRING_CHOOSER] = shakes;
                  gBattlescriptCurrInstr = BattleScript_ShakeBallThrow;
              }
          }
      }
}

/** static void Cmd_givecaughtmon(void) */
